-- 210 (14/11, lô 46): 32 bài ĐỌC B2 cho cây Luyện tập (B2-CE-1 đến CE-5, các dòng « Cần soạn » của Excel kế hoạch).
-- Sinh bởi scripts/nhap/lo46_doc_b2.mjs. Mỗi bài một câu lệnh (CTE ghi exercises + questions). B2-CE-5 có time_limit (40, 20, 60, 60 phút).
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce018q906u', 'practice', 'Lecture B2 : faut-il payer pour voir un médecin ?', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez cet article dans un journal francophone. Répondez aux questions en choisissant la bonne réponse.</p>', '<p><strong>Consultations : faut-il faire payer davantage les patients ?</strong></p><p>Le gouvernement envisage de doubler la participation forfaitaire demandée à chaque consultation : le patient paierait désormais deux euros de sa poche, sans remboursement possible. Pour ses partisans, la mesure responsabiliserait les malades ; pour ses adversaires, elle éloignerait des soins ceux qui en ont le plus besoin.</p><p>Les défenseurs du projet avancent d''abord un argument financier : l''assurance maladie accumule les déficits, et chaque économie compte. Ils rappellent ensuite que la gratuité apparente fait oublier le coût réel des soins. Une consultation coûte en effet une trentaine d''euros à la collectivité, alors que beaucoup de patients ont l''impression qu''elle ne coûte rien. Selon eux, payer une petite somme inciterait chacun à consulter quand c''est vraiment nécessaire.</p><p>Les opposants répondent que cette logique repose sur une illusion. Plusieurs études montrent que même une somme modeste suffit à faire renoncer les ménages aux revenus faibles. Ces patients retardent alors des soins, laissent une maladie s''aggraver et finissent parfois aux urgences, où leur prise en charge coûte beaucoup plus cher. L''économie réalisée au départ serait donc effacée, voire dépassée, quelques mois plus tard.</p><p>Entre ces deux positions, certains médecins proposent une autre piste. Dans leurs cabinets, environ un patient sur vingt ne se présente pas au rendez-vous, sans même prévenir. Plutôt que de faire payer toutes les consultations, pourquoi ne pas faire payer ces absences, qui allongent les délais pour tout le monde ?</p><p>Au fond, la question dépasse les chiffres. Ce qui est en jeu, c''est l''idée d''un système dans lequel chacun se soigne selon ses besoins, et non selon ses moyens.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la participation forfaitaire : khoản đóng cố định\n• responsabiliser (verbe) : làm cho có trách nhiệm\n• renoncer à (verbe) : từ bỏ\n• une prise en charge : việc tiếp nhận, chi trả điều trị\n• un rendez-vous non honoré : cuộc hẹn bỏ không đến","explications":"• Bài nghị luận B2 hay đi theo thứ tự: đề tài → luận điểm → phản đề → hướng khác → kết luận. Đánh dấu chữ mở đầu mỗi đoạn (« Les défenseurs », « Les opposants », « Entre ces deux positions »).\n• Câu hỏi đi theo thứ tự văn bản: câu 2 thường nằm ở đoạn 2, câu cuối ở đoạn kết.","kyNang":"B2-CE-1","vong":"hoc","thuTu":3}'::jsonb, '2026-11-14T20:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8px000', 'b2ce018q906u', 1, 'qcm', 'Quel est le sujet principal de l''article ?', '{"options":["Une hausse du salaire des médecins généralistes en ville.","La fermeture de nombreux cabinets médicaux à la campagne.","Une mesure qui augmenterait ce que paient les patients."]}'::jsonb, '{"answer":2}'::jsonb, 'Đoạn mở bài nêu đề tài: « doubler la participation forfaitaire demandée à chaque consultation ».'), ('qmwgmy8px001', 'b2ce018q906u', 2, 'qcm', 'Dans le deuxième paragraphe, l''auteur présente…', '{"options":["sa propre opinion sur le déficit de l''assurance maladie.","les critiques des syndicats de médecins contre le projet.","les arguments en faveur du projet."]}'::jsonb, '{"answer":2}'::jsonb, 'Đoạn 2 là luận điểm của phe ủng hộ: « Les défenseurs du projet avancent d''abord un argument financier ».'), ('qmwgmy8px002', 'b2ce018q906u', 3, 'qcm', 'Selon les partisans de la mesure, la gratuité apparente des soins…', '{"options":["attire vers les cabinets des patients venus d''autres régions.","cache leur véritable coût.","pousse les médecins à recevoir plus de patients chaque jour."]}'::jsonb, '{"answer":1}'::jsonb, '« la gratuité apparente fait oublier le coût réel des soins ».'), ('qmwgmy8px003', 'b2ce018q906u', 4, 'qcm', 'Quel argument les opposants avancent-ils ?', '{"options":["Les médecins refuseront de demander cet argent aux patients.","Les patients aisés consulteront moins souvent qu''avant.","Une petite somme décourage déjà les plus modestes."]}'::jsonb, '{"answer":2}'::jsonb, 'Đoạn 3 là phản đề: « même une somme modeste suffit à faire renoncer les ménages aux revenus faibles ».'), ('qmwgmy8py004', 'b2ce018q906u', 5, 'qcm', 'Pourquoi, selon les opposants, l''économie serait-elle une illusion ?', '{"options":["La mesure demanderait trop d''employés pour être appliquée.","Les soins retardés finissent par coûter plus cher.","Les patients se feraient rembourser par leur mutuelle privée."]}'::jsonb, '{"answer":1}'::jsonb, '« L''économie réalisée au départ serait donc effacée, voire dépassée, quelques mois plus tard » vì bệnh nặng thêm rồi vào cấp cứu, « coûte beaucoup plus cher ».'), ('qmwgmy8py005', 'b2ce018q906u', 6, 'qcm', 'Que proposent certains médecins ?', '{"options":["Faire payer les rendez-vous manqués sans prévenir.","Supprimer complètement la participation payée par les patients.","Augmenter le prix de toutes les consultations du soir."]}'::jsonb, '{"answer":0}'::jsonb, '« pourquoi ne pas faire payer ces absences »: tức bệnh nhân không đến mà « sans même prévenir ».'), ('qmwgmy8py006', 'b2ce018q906u', 7, 'qcm', 'Dans sa conclusion, l''auteur suggère que le débat porte surtout sur…', '{"options":["la meilleure façon d''organiser les services d''urgence.","un principe d''égalité face aux soins.","la rentabilité des cabinets installés dans les grandes villes."]}'::jsonb, '{"answer":1}'::jsonb, '« chacun se soigne selon ses besoins, et non selon ses moyens ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce028qb06v', 'practice', 'Lecture B2 : le livre numérique a-t-il tué le papier ?', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez cet article dans un journal francophone. Répondez aux questions en choisissant la bonne réponse.</p>', '<p><strong>Le livre numérique n''a pas tué le papier</strong></p><p>Il y a quinze ans, on annonçait la mort du livre imprimé. Les liseuses allaient remplacer les bibliothèques, comme les fichiers musicaux avaient remplacé les disques. Aujourd''hui, le constat est tout autre : en France, le livre numérique ne représente qu''une petite part des ventes, autour de dix pour cent selon les années.</p><p>Plusieurs raisons expliquent cette résistance. D''abord, le prix : un livre numérique coûte à peine moins cher que sa version de poche, alors qu''on ne peut ni le prêter ni le revendre. Ensuite, l''objet lui-même : beaucoup de lecteurs disent mieux retenir ce qu''ils lisent sur papier, et plusieurs études sur la compréhension leur donnent en partie raison, surtout pour les textes longs et difficiles.</p><p>Le numérique a pourtant trouvé sa place. Il s''est imposé chez les grands lecteurs de romans policiers et sentimentaux, qui lisent plusieurs livres par semaine, et chez les voyageurs, heureux d''emporter cent titres dans une poche. Le livre audio, lui, connaît une croissance rapide, porté par les trajets quotidiens et le sport.</p><p>Paradoxalement, c''est peut-être internet qui a sauvé le papier. Sur les réseaux sociaux, de jeunes lecteurs partagent leurs coups de cœur en vidéo, et ces recommandations ont relancé la vente de romans imprimés chez les adolescents. Les libraires constatent que ces jeunes veulent un bel objet, qu''on expose sur une étagère et qu''on prend en photo.</p><p>Plutôt qu''une guerre, il faudrait donc parler d''une répartition des rôles : chaque support répond à un usage. La vraie menace pour le livre n''est pas l''écran de la liseuse, mais celui du téléphone, qui grignote peu à peu le temps que nous consacrons à la lecture.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une liseuse : máy đọc sách điện tử\n• un constat : nhận định từ thực tế\n• s''imposer (verbe) : chiếm được chỗ đứng\n• un coup de cœur : thứ mình rất thích\n• grignoter (verbe) : gặm nhấm, lấn dần","explications":"• Mỗi đoạn có một vai trò: bối cảnh, giải thích, nhượng bộ, ví dụ, kết luận. Câu hỏi « sert à… », « a pour rôle de… » hỏi vai trò đó, không hỏi chi tiết.\n• Các từ nối « D''abord, Ensuite, pourtant, Paradoxalement, donc » cho biết đoạn đang làm gì.","isPremium":true,"price":19000,"kyNang":"B2-CE-1","vong":"hoc","thuTu":4}'::jsonb, '2026-11-14T20:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py007', 'b2ce028qb06v', 1, 'qcm', 'Le premier paragraphe sert à…', '{"options":["rappeler une prédiction qui ne s''est pas réalisée.","annoncer la fermeture prochaine de nombreuses bibliothèques.","présenter les ventes de liseuses dans plusieurs pays d''Europe."]}'::jsonb, '{"answer":0}'::jsonb, '« on annonçait la mort du livre imprimé… le constat est tout autre ».'), ('qmwgmy8py008', 'b2ce028qb06v', 2, 'qcm', 'Selon l''article, le prix freine le livre numérique parce qu''il…', '{"options":["reste proche de celui d''un livre de poche.","augmente chaque année plus vite que celui des livres imprimés.","change beaucoup d''une plateforme de vente à une autre."]}'::jsonb, '{"answer":0}'::jsonb, '« un livre numérique coûte à peine moins cher que sa version de poche ».'), ('qmwgmy8py009', 'b2ce028qb06v', 3, 'qcm', 'Qu''apprend-on sur la mémorisation ?', '{"options":["Des études confirment en partie l''avantage du papier.","Les lecteurs retiennent mieux les textes lus sur un écran.","Aucune recherche sérieuse n''a encore été menée sur ce sujet."]}'::jsonb, '{"answer":0}'::jsonb, '« plusieurs études sur la compréhension leur donnent en partie raison ».'), ('qmwgmy8py00a', 'b2ce028qb06v', 4, 'qcm', 'Le troisième paragraphe a pour rôle de…', '{"options":["critiquer les habitudes de lecture des voyageurs pressés.","conclure l''article en donnant l''avis personnel de l''auteur.","nuancer en montrant où le numérique réussit."]}'::jsonb, '{"answer":2}'::jsonb, 'Chữ « pourtant » báo hiệu nhượng bộ: « Le numérique a pourtant trouvé sa place ».'), ('qmwgmy8py00b', 'b2ce028qb06v', 5, 'qcm', 'Quel public a adopté la lecture numérique ?', '{"options":["Les jeunes enfants qui apprennent à lire.","Les étudiants en lettres et en histoire.","Les gros lecteurs de romans de genre."]}'::jsonb, '{"answer":2}'::jsonb, '« chez les grands lecteurs de romans policiers et sentimentaux ».'), ('qmwgmy8py00c', 'b2ce028qb06v', 6, 'qcm', 'Quel paradoxe l''auteur souligne-t-il ?', '{"options":["Les libraires vendent maintenant surtout des liseuses.","Les adolescents ne lisent plus que sur leur téléphone.","Internet a relancé le livre papier chez les jeunes."]}'::jsonb, '{"answer":2}'::jsonb, '« c''est peut-être internet qui a sauvé le papier »: các video giới thiệu sách « ont relancé la vente de romans imprimés chez les adolescents ».'), ('qmwgmy8py00d', 'b2ce028qb06v', 7, 'qcm', 'Selon la conclusion, quelle est la véritable menace pour la lecture ?', '{"options":["Le prix trop élevé des nouvelles liseuses.","Le temps passé sur le téléphone.","La disparition progressive des petites librairies."]}'::jsonb, '{"answer":1}'::jsonb, '« celui du téléphone, qui grignote peu à peu le temps que nous consacrons à la lecture ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce038qc06w', 'practice', 'Lecture B2 : les parcs naturels payants', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez cet article dans un journal francophone. Répondez aux questions en choisissant la bonne réponse.</p>', '<p><strong>Faut-il faire payer l''entrée des espaces naturels ?</strong></p><p>Sur certains sites très fréquentés du littoral méditerranéen, l''accès aux plages et aux criques se fait déjà sur réservation pendant l''été. D''autres espaces naturels envisagent d''aller plus loin : faire payer l''entrée, comme dans de nombreux parcs nationaux américains. L''idée choque en France, où la nature est considérée comme un bien commun, ouvert à tous.</p><p>Le problème est pourtant réel. Sur certains sentiers, la fréquentation a doublé en dix ans. Érosion des sols, déchets, plantes piétinées, animaux dérangés : les gardes ne suffisent plus. Nous accueillons parfois cinq mille personnes par jour sur un site prévu pour mille, explique la responsable d''un parc des Pyrénées.</p><p>Un droit d''entrée, même modeste, permettrait de financer l''entretien des chemins et de recruter des gardes supplémentaires. Il aurait aussi un effet dissuasif sur les visiteurs de passage, qui viennent prendre une photo, restent dix minutes et repartent en laissant leurs déchets derrière eux.</p><p>Mais qui renoncerait le plus vite ? Pas les touristes étrangers, prêts à payer, mais les familles modestes des villes voisines, pour qui ces espaces sont souvent le seul lieu de vacances accessible. Faire payer, ce serait transformer la nature en produit de loisir réservé à ceux qui en ont les moyens.</p><p>D''où l''intérêt de solutions intermédiaires : une réservation gratuite pour limiter le nombre de visiteurs les jours de forte affluence, la gratuité pour les habitants de la région, ou une taxe sur les parkings plutôt que sur les marcheurs. Réguler sans exclure : c''est tout l''enjeu des prochaines années.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une crique : vịnh nhỏ\n• la fréquentation : lượng người đến\n• piétiner (verbe) : giẫm nát\n• dissuasif (adjectif) : có tác dụng ngăn cản\n• l''affluence (nom féminin) : lúc đông người","explications":"• Hỏi vai trò đoạn thì đọc câu đầu và câu cuối của đoạn trước: thường đó là câu chủ đề.\n• Câu hỏi tu từ (« Mais qui renoncerait le plus vite ? ») hay mở đầu một phản biện.","isPremium":true,"price":19000,"kyNang":"B2-CE-1","vong":"hoc","thuTu":5}'::jsonb, '2026-11-14T20:00:02.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py00e', 'b2ce038qc06w', 1, 'qcm', 'Quel est le rôle du premier paragraphe ?', '{"options":["Raconter l''histoire de la création des parcs nationaux.","Décrire en détail le fonctionnement des parcs américains.","Présenter une idée qui heurte une conception française."]}'::jsonb, '{"answer":2}'::jsonb, '« L''idée choque en France, où la nature est considérée comme un bien commun ».'), ('qmwgmy8py00f', 'b2ce038qc06w', 2, 'qcm', 'Le deuxième paragraphe sert surtout à…', '{"options":["présenter la vie quotidienne des gardes dans les Pyrénées.","proposer une première solution pour protéger les sentiers.","montrer que le problème de fréquentation est réel."]}'::jsonb, '{"answer":2}'::jsonb, 'Câu chủ đề của đoạn: « Le problème est pourtant réel », sau đó là số liệu và lời nhân chứng.'), ('qmwgmy8py00g', 'b2ce038qc06w', 3, 'qcm', 'Que montre la phrase de la responsable du parc ?', '{"options":["Le site reçoit beaucoup plus de monde que prévu.","Les gardes refusent désormais de travailler le week-end.","Le parc manque de visiteurs en dehors des vacances."]}'::jsonb, '{"answer":0}'::jsonb, '« cinq mille personnes par jour sur un site prévu pour mille ».'), ('qmwgmy8py00h', 'b2ce038qc06w', 4, 'qcm', 'D''après le troisième paragraphe, un droit d''entrée aurait deux avantages :', '{"options":["attirer des touristes étrangers et créer des emplois locaux.","faire baisser le prix des hôtels et protéger les animaux.","financer l''entretien et décourager certains visiteurs."]}'::jsonb, '{"answer":2}'::jsonb, '« financer l''entretien des chemins » và « un effet dissuasif sur les visiteurs de passage ».'), ('qmwgmy8py00i', 'b2ce038qc06w', 5, 'qcm', 'Dans le quatrième paragraphe, l''auteur…', '{"options":["soulève une objection d''ordre social.","défend sans réserve le principe d''un droit d''entrée.","présente des chiffres sur le tourisme étranger en France."]}'::jsonb, '{"answer":0}'::jsonb, 'Đoạn 4 phản biện: thiên nhiên sẽ thành « produit de loisir réservé à ceux qui en ont les moyens ».'), ('qmwgmy8py00j', 'b2ce038qc06w', 6, 'qcm', 'Selon l''article, qui serait le plus touché par un droit d''entrée ?', '{"options":["Les touristes étrangers venus pour quelques jours.","Les gardes et les employés des parcs naturels.","Les familles modestes qui vivent près des sites."]}'::jsonb, '{"answer":2}'::jsonb, '« les familles modestes des villes voisines »; ngược lại khách nước ngoài « prêts à payer ».'), ('qmwgmy8py00k', 'b2ce038qc06w', 7, 'qcm', 'Quelle position l''auteur défend-il finalement ?', '{"options":["Faire payer l''entrée à tous les visiteurs sans exception.","Limiter la fréquentation sans écarter une partie du public.","Interdire l''accès aux sites les plus fragiles pendant l''été."]}'::jsonb, '{"answer":1}'::jsonb, 'Câu kết: « Réguler sans exclure : c''est tout l''enjeu des prochaines années ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce048qc06x', 'practice', 'Lecture B2 : les zoos ont-ils encore un sens ?', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez cet article dans un journal francophone. Répondez aux questions en choisissant la bonne réponse.</p>', '<p><strong>Les zoos ont-ils encore un sens ?</strong></p><p>Chaque année, des millions de visiteurs se pressent dans les parcs zoologiques français. Pourtant, ces lieux sont de plus en plus contestés. Après l''interdiction progressive des animaux sauvages dans les cirques, certaines associations réclament désormais la fermeture pure et simple des zoos.</p><p>Pour leurs détracteurs, l''enfermement est incompatible avec le bien-être animal. Un ours ou un éléphant parcourt naturellement des dizaines de kilomètres par jour ; aucun enclos, aussi grand soit-il, ne peut remplacer ce territoire. Les comportements répétitifs observés chez certains animaux captifs, comme les allers-retours incessants le long d''une grille, seraient le signe d''une souffrance.</p><p>Les responsables de zoos répondent que leur rôle a profondément changé. Les établissements modernes participent à des programmes de reproduction d''espèces menacées, dont certaines ont pu être réintroduites dans la nature. Ils financent aussi des projets de protection sur le terrain et mènent des recherches impossibles à conduire en milieu sauvage.</p><p>Reste l''argument pédagogique : voir un animal en vrai donnerait aux enfants l''envie de protéger la nature. Les opposants en doutent. Selon eux, un documentaire en apprend davantage sur la vie d''un guépard qu''un animal qui dort derrière une vitre.</p><p>Sans doute la question n''appelle-t-elle pas de réponse unique. Tous les zoos ne se valent pas, et la distinction entre un parc engagé dans la conservation et un simple lieu de divertissement mérite d''être faite. Peut-être faudrait-il réserver la captivité aux espèces dont la survie en dépend réellement.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un détracteur : người chỉ trích\n• un enclos : chuồng có rào\n• captif (adjectif) : bị nuôi nhốt\n• réintroduire (verbe) : thả lại về tự nhiên\n• se valoir (verbe) : ngang nhau, như nhau","explications":"• Phân biệt ý của TỪNG PHE: « Pour leurs détracteurs », « Les responsables de zoos répondent », « Les opposants en doutent ». Phương án nhiễu hay gán ý phe này cho phe kia.\n• Kết luận dùng « Sans doute », « Peut-être »: tác giả đưa ý dè dặt, không chọn phe tuyệt đối.","isPremium":true,"price":19000,"kyNang":"B2-CE-1","vong":"hoc","thuTu":6}'::jsonb, '2026-11-14T20:00:03.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py00l', 'b2ce048qc06x', 1, 'qcm', 'Que réclament certaines associations ?', '{"options":["L''interdiction des animaux sauvages dans les cirques.","La fermeture complète des zoos.","Des enclos plus grands pour les ours et les éléphants."]}'::jsonb, '{"answer":1}'::jsonb, '« la fermeture pure et simple des zoos ». Lệnh cấm ở rạp xiếc là việc đã có (« Après l''interdiction progressive »).'), ('qmwgmy8py00m', 'b2ce048qc06x', 2, 'qcm', 'Quel est l''argument principal des détracteurs des zoos ?', '{"options":["La captivité ne respecte pas les besoins des animaux.","Les visiteurs dérangent les animaux en faisant trop de bruit.","Les zoos coûtent beaucoup trop cher aux villes qui les financent."]}'::jsonb, '{"answer":0}'::jsonb, '« l''enfermement est incompatible avec le bien-être animal ».'), ('qmwgmy8py00n', 'b2ce048qc06x', 3, 'qcm', 'Les comportements répétitifs des animaux captifs sont présentés comme…', '{"options":["une réaction aux nombreux visiteurs du week-end.","une forme de jeu tout à fait naturelle.","un indice possible de souffrance."]}'::jsonb, '{"answer":2}'::jsonb, '« seraient le signe d''une souffrance ». Chú ý thức điều kiện « seraient »: người phản đối cho là vậy.'), ('qmwgmy8py00o', 'b2ce048qc06x', 4, 'qcm', 'Le troisième paragraphe présente…', '{"options":["la réponse des défenseurs des zoos.","un nouvel argument des associations de protection animale.","la conclusion personnelle de l''auteur sur la question."]}'::jsonb, '{"answer":0}'::jsonb, '« Les responsables de zoos répondent que leur rôle a profondément changé ».'), ('qmwgmy8py00p', 'b2ce048qc06x', 5, 'qcm', 'Selon les responsables de zoos, les établissements modernes…', '{"options":["aident à sauver des espèces menacées.","accueillent surtout des animaux nés dans la nature.","refusent de participer aux recherches scientifiques."]}'::jsonb, '{"answer":0}'::jsonb, '« participent à des programmes de reproduction d''espèces menacées ».'), ('qmwgmy8py00q', 'b2ce048qc06x', 6, 'qcm', 'Comment les opposants répondent-ils à l''argument pédagogique ?', '{"options":["Les enfants préfèrent les animaux de compagnie.","Un documentaire serait plus instructif.","Les écoles n''organisent plus de sorties au zoo."]}'::jsonb, '{"answer":1}'::jsonb, '« un documentaire en apprend davantage sur la vie d''un guépard ».'), ('qmwgmy8py00r', 'b2ce048qc06x', 7, 'qcm', 'Quelle est la position de l''auteur dans la conclusion ?', '{"options":["Tous les zoos doivent fermer dans les prochaines années.","Il faut juger chaque zoo selon sa mission réelle.","Les zoos sont indispensables à l''éducation des enfants."]}'::jsonb, '{"answer":1}'::jsonb, '« Tous les zoos ne se valent pas » và cần phân biệt « un parc engagé dans la conservation et un simple lieu de divertissement ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce058qc06y', 'practice', 'Lecture B2 : la mode jetable', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez cet article dans un journal francophone. Répondez aux questions en choisissant la bonne réponse.</p>', '<p><strong>La mode jetable : à qui la faute ?</strong></p><p>Un tee-shirt à cinq euros, une robe à quinze : la mode n''a jamais été aussi bon marché. En vingt ans, le nombre de vêtements achetés par personne a presque doublé, tandis que la durée pendant laquelle nous les portons a fortement diminué. Certains vêtements ne sont mis que quelques fois avant de finir au fond d''un placard, ou à la poubelle.</p><p>Les grandes marques portent une lourde responsabilité. Certaines enseignes proposent chaque semaine de nouveaux modèles et entretiennent le sentiment qu''un vêtement est vite démodé. Pour produire à si bas prix, elles fabriquent dans des pays où les salaires sont très faibles et utilisent des matières synthétiques issues du pétrole.</p><p>Mais il serait trop simple d''accuser uniquement les industriels. Ce sont bien les consommateurs qui remplissent les paniers en ligne, encouragés par les réseaux sociaux où l''on se montre rarement deux fois dans la même tenue. Beaucoup affirment vouloir consommer de façon responsable, mais achètent quand même au prix le plus bas.</p><p>Plusieurs pistes existent. Des règles obligent désormais les marques à informer sur l''impact environnemental de leurs produits, et un malus pourrait frapper les vêtements les plus polluants. La seconde main, elle, connaît un succès spectaculaire, même si elle sert parfois à revendre pour racheter encore plus.</p><p>Au fond, la question n''est pas seulement de savoir qui est coupable, mais ce que nous attendons d''un vêtement. Tant qu''il sera considéré comme un produit jetable, aucune loi ne suffira à changer nos habitudes.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• jetable (adjectif) : dùng một lần rồi bỏ\n• une enseigne : chuỗi cửa hàng, nhãn hàng\n• démodé (adjectif) : lỗi mốt\n• un malus : khoản phạt thêm\n• la seconde main : đồ cũ, hàng đã qua sử dụng","explications":"• Câu hỏi về cách tổ chức bài: gạch chân câu đầu mỗi đoạn rồi tóm mỗi đoạn trong 2, 3 chữ.\n• « Mais il serait trop simple de… » là cách quen thuộc để chuyển sang ý ngược lại mà không phủ nhận ý trước.","isPremium":true,"price":19000,"kyNang":"B2-CE-1","vong":"hoc","thuTu":7}'::jsonb, '2026-11-14T20:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py00s', 'b2ce058qc06y', 1, 'qcm', 'Comment l''article est-il organisé ?', '{"options":["Un constat, deux responsables, des solutions, une conclusion.","Une comparaison entre deux pays, puis l''avis d''un expert.","Un témoignage, puis des chiffres, puis un appel au boycott."]}'::jsonb, '{"answer":0}'::jsonb, 'Thứ tự: hiện trạng, rồi « Les grandes marques portent une lourde responsabilité », rồi « il serait trop simple d''accuser uniquement les industriels », rồi « Plusieurs pistes existent », cuối cùng « Au fond ».'), ('qmwgmy8py00t', 'b2ce058qc06y', 2, 'qcm', 'Quel phénomène le premier paragraphe décrit-il ?', '{"options":["Les vêtements fabriqués en France sont de meilleure qualité.","On achète plus de vêtements et on les garde moins.","Le prix des vêtements a beaucoup augmenté en vingt ans."]}'::jsonb, '{"answer":1}'::jsonb, '« le nombre de vêtements achetés par personne a presque doublé, tandis que la durée pendant laquelle nous les portons a fortement diminué ».'), ('qmwgmy8py00u', 'b2ce058qc06y', 3, 'qcm', 'Que reproche-t-on aux grandes marques ?', '{"options":["De fabriquer leurs collections seulement en Europe.","De faire croire qu''un vêtement se démode très vite.","De vendre leurs vêtements uniquement sur internet."]}'::jsonb, '{"answer":1}'::jsonb, '« entretiennent le sentiment qu''un vêtement est vite démodé ».'), ('qmwgmy8py00v', 'b2ce058qc06y', 4, 'qcm', 'Quelle phrase introduit la responsabilité des consommateurs ?', '{"options":["Au fond, la question n''est pas seulement de savoir qui est coupable, mais ce que nous attendons d''un vêtement.","Les grandes marques portent une lourde responsabilité.","Mais il serait trop simple d''accuser uniquement les industriels."]}'::jsonb, '{"answer":2}'::jsonb, '« Mais » đổi hướng: sau nhãn hàng là người mua, « Ce sont bien les consommateurs qui remplissent les paniers en ligne ».'), ('qmwgmy8py00w', 'b2ce058qc06y', 5, 'qcm', 'Quelle contradiction l''auteur relève-t-il chez les consommateurs ?', '{"options":["Ils critiquent les réseaux sociaux mais y passent des heures.","Ils veulent être responsables mais choisissent le moins cher.","Ils aiment la seconde main mais n''osent pas en acheter."]}'::jsonb, '{"answer":1}'::jsonb, '« affirment vouloir consommer de façon responsable, mais achètent quand même au prix le plus bas ».'), ('qmwgmy8py00x', 'b2ce058qc06y', 6, 'qcm', 'Quelle limite de la seconde main l''auteur signale-t-il ?', '{"options":["Elle est désormais interdite sur les sites en ligne.","Elle reste réservée aux personnes les plus aisées.","Elle peut pousser à acheter encore davantage."]}'::jsonb, '{"answer":2}'::jsonb, '« elle sert parfois à revendre pour racheter encore plus ».'), ('qmwgmy8py00y', 'b2ce058qc06y', 7, 'qcm', 'Selon la conclusion, que faut-il changer avant tout ?', '{"options":["Les lois sur la fabrication des tissus synthétiques.","Notre façon de considérer le vêtement.","Le nombre de magasins dans les centres-villes."]}'::jsonb, '{"answer":1}'::jsonb, '« ce que nous attendons d''un vêtement… Tant qu''il sera considéré comme un produit jetable, aucune loi ne suffira ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce068qc06z', 'practice', 'Lecture B2 : le prix des médicaments', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez cet article dans un journal francophone. Répondez aux questions en choisissant la bonne réponse.</p>', '<p><strong>Médicaments innovants : le prix de la guérison</strong></p><p>Un traitement contre une maladie génétique rare vient d''être autorisé en Europe. Une seule injection pourrait guérir des enfants jusqu''ici condamnés. Son prix : près de deux millions d''euros. Ce cas, loin d''être isolé, relance une question que les systèmes de santé ne peuvent plus éviter : combien une société peut-elle payer pour soigner ?</p><p>Les laboratoires justifient ces montants par le coût de la recherche. Développer un médicament prend souvent plus de dix ans, et la grande majorité des molécules testées n''arrivent jamais sur le marché. Quand la maladie ne touche que quelques centaines de patients, ajoutent-ils, il faut bien amortir ces dépenses sur un petit nombre de traitements.</p><p>Des économistes de la santé contestent ce raisonnement. Selon eux, les prix sont moins fixés en fonction des coûts réels que de ce que les États sont prêts à payer. Ils rappellent aussi qu''une partie de la recherche initiale est financée par des laboratoires publics et des universités, donc par les contribuables.</p><p>Ces prix posent un problème très concret. Le budget de l''assurance maladie n''est pas illimité : chaque euro consacré à un traitement coûteux ne peut pas servir ailleurs, par exemple à la prévention ou aux soins courants. Certains pays commencent déjà à retarder l''accès à des médicaments jugés trop chers.</p><p>Pour sortir de l''impasse, plusieurs pistes sont étudiées : négocier les prix à l''échelle européenne pour peser davantage, ou ne payer le laboratoire que si le traitement fonctionne réellement chez le patient. Car l''enjeu n''est pas de punir l''innovation, mais de garantir qu''elle profite à tous.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une molécule : phân tử, hoạt chất\n• amortir (verbe) : khấu hao, bù lại chi phí\n• un contribuable : người nộp thuế\n• une impasse : ngõ cụt, bế tắc\n• peser (verbe) : có sức nặng, có ảnh hưởng","explications":"• Ví dụ ở đầu bài thường không phải đề tài chính: hãy tìm câu « Ce cas… relance une question » để thấy vấn đề chung.\n• Đoạn có « contestent », « répondent », « en doutent » là đoạn phản biện.","isPremium":true,"price":19000,"kyNang":"B2-CE-1","vong":"hoc","thuTu":8}'::jsonb, '2026-11-14T20:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py00z', 'b2ce068qc06z', 1, 'qcm', 'Quel est le rôle de l''exemple donné au début de l''article ?', '{"options":["Faire connaître un traitement à un large public.","Introduire un problème général à partir d''un cas.","Raconter l''histoire d''un enfant soigné en Europe."]}'::jsonb, '{"answer":1}'::jsonb, '« Ce cas, loin d''être isolé, relance une question »: ví dụ dẫn vào vấn đề chung.'), ('qmwgmy8py010', 'b2ce068qc06z', 2, 'qcm', 'Comment les laboratoires justifient-ils leurs prix ?', '{"options":["Par le salaire élevé des chercheurs européens.","Par le prix des usines construites en Europe.","Par la durée et les échecs de la recherche."]}'::jsonb, '{"answer":2}'::jsonb, '« Développer un médicament prend souvent plus de dix ans, et la grande majorité des molécules testées n''arrivent jamais sur le marché ».'), ('qmwgmy8py011', 'b2ce068qc06z', 3, 'qcm', 'Selon les laboratoires, pourquoi les traitements des maladies rares sont-ils si chers ?', '{"options":["Les États refusent d''aider la recherche sur ces maladies.","Les frais sont répartis sur peu de patients.","Ces maladies demandent des hôpitaux spécialisés."]}'::jsonb, '{"answer":1}'::jsonb, '« amortir ces dépenses sur un petit nombre de traitements ».'), ('qmwgmy8py012', 'b2ce068qc06z', 4, 'qcm', 'Le troisième paragraphe…', '{"options":["donne de nouveaux exemples de maladies génétiques rares.","explique comment fonctionne l''assurance maladie en France.","remet en cause l''argument des laboratoires."]}'::jsonb, '{"answer":2}'::jsonb, '« Des économistes de la santé contestent ce raisonnement ».'), ('qmwgmy8py013', 'b2ce068qc06z', 5, 'qcm', 'D''après les économistes, les prix dépendent surtout…', '{"options":["de ce que les États acceptent de payer.","du temps nécessaire pour fabriquer chaque dose.","du nombre de pays qui autorisent le médicament."]}'::jsonb, '{"answer":0}'::jsonb, '« moins fixés en fonction des coûts réels que de ce que les États sont prêts à payer ».'), ('qmwgmy8py014', 'b2ce068qc06z', 6, 'qcm', 'Quelle conséquence le quatrième paragraphe met-il en avant ?', '{"options":["Les médecins prescrivent moins de médicaments.","L''argent dépensé manque pour d''autres soins.","Les patients partent se soigner à l''étranger."]}'::jsonb, '{"answer":1}'::jsonb, '« chaque euro consacré à un traitement coûteux ne peut pas servir ailleurs ».'), ('qmwgmy8py015', 'b2ce068qc06z', 7, 'qcm', 'Quelle solution l''article évoque-t-il ?', '{"options":["Confier toute la recherche aux universités publiques.","Interdire les traitements dépassant un certain prix.","Payer seulement si le traitement est efficace."]}'::jsonb, '{"answer":2}'::jsonb, '« ne payer le laboratoire que si le traitement fonctionne réellement chez le patient ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce078qc070', 'practice', 'Lecture B2 : le salaire à vie', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez cet article dans un journal francophone. Répondez aux questions en choisissant la bonne réponse.</p>', '<p><strong>Un revenu pour tous : utopie ou solution ?</strong></p><p>Et si chacun recevait chaque mois une somme d''argent, qu''il ait un emploi ou non ? L''idée d''un revenu versé à tous, sans condition, que certains appellent un salaire à vie, n''est plus réservée à quelques penseurs. Des expériences ont été menées dans plusieurs pays, et des candidats en ont fait un thème de campagne.</p><p>Ses partisans y voient d''abord un moyen de lutter contre la pauvreté. Les aides actuelles sont complexes, et une partie des personnes qui y ont droit ne les demandent pas, par manque d''information ou par honte. Un revenu automatique supprimerait ces obstacles.</p><p>Ils avancent aussi un argument tourné vers l''avenir : si l''automatisation détruit de nombreux emplois, il faudra bien trouver un autre moyen de faire vivre la population. Ce revenu permettrait en outre de reconnaître des activités utiles mais non payées, comme s''occuper d''un parent âgé.</p><p>Les critiques portent d''abord sur le coût. Verser une somme suffisante à chaque adulte représenterait une dépense considérable, qu''il faudrait financer par de lourdes hausses d''impôts. D''autres craignent que certains renoncent à travailler. Sur ce point pourtant, les expériences menées n''ont pas montré de baisse nette de l''activité : dans plusieurs cas, les bénéficiaires n''ont pas moins travaillé, et se disaient moins stressés.</p><p>Reste une question de fond, que les chiffres ne tranchent pas : le travail doit-il rester la condition principale pour avoir sa place dans la société ? Selon la réponse que l''on donne, ce revenu apparaît comme une utopie dangereuse ou comme une étape logique.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• sans condition : vô điều kiện\n• l''automatisation (nom féminin) : tự động hoá\n• un bénéficiaire : người được hưởng\n• trancher (verbe) : phân xử, giải quyết dứt khoát\n• une utopie : điều không tưởng","explications":"• Đọc theo lập luận: mỗi khi gặp « d''abord », « aussi », « en outre », hãy đếm số lý lẽ của từng phe.\n• « Sur ce point pourtant » báo hiệu tác giả dùng dữ kiện để bác một lo ngại vừa nêu.","isPremium":true,"price":19000,"kyNang":"B2-CE-1","vong":"on","thuTu":9}'::jsonb, '2026-11-14T20:00:06.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py016', 'b2ce078qc070', 1, 'qcm', 'L''article présente le revenu pour tous comme une idée…', '{"options":["abandonnée après plusieurs expériences ratées.","qui intéresse désormais au-delà de quelques penseurs.","que tous les pays européens ont déjà adoptée depuis plusieurs années."]}'::jsonb, '{"answer":1}'::jsonb, '« n''est plus réservée à quelques penseurs ».'), ('qmwgmy8py017', 'b2ce078qc070', 2, 'qcm', 'Selon les partisans, quel défaut ont les aides actuelles ?', '{"options":["Elles coûtent plus cher qu''un revenu versé à tous.","Elles sont versées trop tard aux familles nombreuses.","Beaucoup de personnes concernées ne les réclament pas."]}'::jsonb, '{"answer":2}'::jsonb, '« une partie des personnes qui y ont droit ne les demandent pas ».'), ('qmwgmy8py018', 'b2ce078qc070', 3, 'qcm', 'Quel argument les partisans tournent-ils vers l''avenir ?', '{"options":["Le vieillissement rapide de la population active dans les pays riches.","La disparition possible d''emplois à cause des machines.","La hausse du prix des logements dans les villes."]}'::jsonb, '{"answer":1}'::jsonb, '« si l''automatisation détruit de nombreux emplois ».'), ('qmwgmy8py019', 'b2ce078qc070', 4, 'qcm', 'Quel exemple d''activité utile mais non payée est cité ?', '{"options":["S''occuper d''un parent âgé.","Faire du bénévolat dans un club sportif.","Garder les enfants de ses voisins."]}'::jsonb, '{"answer":0}'::jsonb, '« comme s''occuper d''un parent âgé ».'), ('qmwgmy8py01a', 'b2ce078qc070', 5, 'qcm', 'Quelle est la première critique adressée à cette idée ?', '{"options":["Son coût très élevé.","Sa complexité administrative.","Son injustice envers les retraités."]}'::jsonb, '{"answer":0}'::jsonb, '« Les critiques portent d''abord sur le coût ».'), ('qmwgmy8py01b', 'b2ce078qc070', 6, 'qcm', 'Que montrent les expériences au sujet du travail ?', '{"options":["Les bénéficiaires n''ont pas cessé de travailler.","Les bénéficiaires ont surtout réduit leurs heures.","Les bénéficiaires ont tous trouvé un meilleur emploi."]}'::jsonb, '{"answer":0}'::jsonb, '« n''ont pas montré de baisse nette de l''activité »: « n''ont pas moins travaillé ».'), ('qmwgmy8py01c', 'b2ce078qc070', 7, 'qcm', 'Selon l''auteur, le débat dépend finalement…', '{"options":["des résultats des prochaines élections nationales.","du montant exact versé chaque mois à chaque adulte.","de la place qu''on donne au travail dans la société."]}'::jsonb, '{"answer":2}'::jsonb, '« le travail doit-il rester la condition principale pour avoir sa place dans la société ? »')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce088qc071', 'practice', 'Lecture B2 : faut-il protéger les langues rares ?', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez cet article dans un journal francophone. Répondez aux questions en choisissant la bonne réponse.</p>', '<p><strong>Faut-il sauver les langues qui disparaissent ?</strong></p><p>Selon plusieurs estimations, près de la moitié des quelque sept mille langues parlées dans le monde pourraient disparaître d''ici la fin du siècle. Régulièrement, une langue perd son dernier locuteur. Faut-il s''en inquiéter, ou accepter qu''il s''agit d''une évolution normale ?</p><p>Pour certains, la disparition des langues fait partie de l''histoire. Le latin s''est éteint en donnant naissance à d''autres langues, et personne ne le regrette vraiment. Dans un monde connecté, parler une langue partagée par des millions de personnes ouvre des portes : comment reprocher à des parents de préférer l''anglais ou l''espagnol pour leurs enfants ?</p><p>Les linguistes répondent qu''une langue n''est pas seulement un outil de communication. Elle contient une manière de voir le monde, ainsi que des connaissances sur les plantes, le climat ou les animaux qui, souvent, ne sont écrites nulle part. Quand une langue meurt, c''est une bibliothèque entière qui brûle.</p><p>Ils contestent aussi l''idée d''une évolution normale. Beaucoup de langues ont reculé parce qu''elles ont été interdites à l''école ou méprisées, et leurs locuteurs ont appris à en avoir honte. Leur disparition n''est donc pas le fruit du hasard, mais souvent de choix politiques.</p><p>Les exemples de renaissance existent : l''hébreu, le gallois ou le maori ont retrouvé des locuteurs grâce à l''école et aux médias. Sauver une langue ne signifie pas renoncer aux langues internationales, mais permettre à ceux qui le souhaitent d''en parler plusieurs. Le bilinguisme, après tout, n''a jamais appauvri personne.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un locuteur : người nói (một ngôn ngữ)\n• s''éteindre (verbe) : tắt, mất đi\n• mépriser (verbe) : khinh thường\n• le fruit du hasard : kết quả ngẫu nhiên\n• appauvrir (verbe) : làm nghèo đi","explications":"• Câu hỏi tu từ trong bài nghị luận mang ý khẳng định ngầm: « comment reprocher… ? » = không nên trách.\n• Hình ảnh ẩn dụ (« une bibliothèque entière qui brûle ») được hỏi để kiểm tra bạn hiểu nghĩa bóng.","isPremium":true,"price":19000,"kyNang":"B2-CE-1","vong":"on","thuTu":10}'::jsonb, '2026-11-14T20:00:07.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py01d', 'b2ce088qc071', 1, 'qcm', 'Comment l''article commence-t-il ?', '{"options":["Par une définition scientifique du mot langue.","Par une estimation chiffrée suivie d''une question.","Par le témoignage du dernier locuteur d''une langue."]}'::jsonb, '{"answer":1}'::jsonb, '« près de la moitié des quelque sept mille langues… pourraient disparaître » rồi câu hỏi « Faut-il s''en inquiéter ».'), ('qmwgmy8py01e', 'b2ce088qc071', 2, 'qcm', 'Dans le deuxième paragraphe, l''exemple du latin sert à montrer…', '{"options":["qu''une langue peut s''éteindre sans être regrettée.","que l''école doit continuer à enseigner les langues mortes.","que les langues anciennes sont encore utiles aujourd''hui."]}'::jsonb, '{"answer":0}'::jsonb, '« Le latin s''est éteint… et personne ne le regrette vraiment ».'), ('qmwgmy8py01f', 'b2ce088qc071', 3, 'qcm', 'Dans ce même paragraphe, le choix de certains parents est présenté comme…', '{"options":["irresponsable.","compréhensible.","rare."]}'::jsonb, '{"answer":1}'::jsonb, 'Câu hỏi tu từ « comment reprocher à des parents de préférer l''anglais » nghĩa là không thể trách họ.'), ('qmwgmy8py01g', 'b2ce088qc071', 4, 'qcm', 'Pour les linguistes, une langue est aussi…', '{"options":["une matière scolaire comme les mathématiques.","un moyen de réussir dans le commerce international.","un ensemble de savoirs souvent non écrits."]}'::jsonb, '{"answer":2}'::jsonb, '« des connaissances sur les plantes, le climat ou les animaux qui, souvent, ne sont écrites nulle part ».'), ('qmwgmy8py01h', 'b2ce088qc071', 5, 'qcm', 'Que signifie l''image de la bibliothèque qui brûle ?', '{"options":["Les bibliothèques refusent les livres anciens.","Des connaissances uniques sont perdues.","Les livres en langues rares sont mal conservés."]}'::jsonb, '{"answer":1}'::jsonb, '« Quand une langue meurt, c''est une bibliothèque entière qui brûle »: mất cả kho tri thức.'), ('qmwgmy8py01i', 'b2ce088qc071', 6, 'qcm', 'Pourquoi les linguistes refusent-ils de parler d''évolution normale ?', '{"options":["Les langues rares sont aujourd''hui en pleine croissance dans la plupart des pays.","Beaucoup de langues ont reculé à cause de décisions politiques.","Le latin n''a jamais réellement disparu d''Europe."]}'::jsonb, '{"answer":1}'::jsonb, '« Leur disparition n''est donc pas le fruit du hasard, mais souvent de choix politiques ».'), ('qmwgmy8py01j', 'b2ce088qc071', 7, 'qcm', 'Quelle idée défend la conclusion ?', '{"options":["Les langues internationales menacent toutes les autres langues.","Il faut enseigner uniquement les langues régionales et rares dans toutes les écoles.","On peut défendre une langue rare et parler une langue internationale."]}'::jsonb, '{"answer":2}'::jsonb, '« ne signifie pas renoncer aux langues internationales, mais permettre à ceux qui le souhaitent d''en parler plusieurs ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce098qc072', 'practice', 'Lecture B2 : un article d''opinion', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez cet article dans un journal francophone. Répondez aux questions en choisissant la bonne réponse.</p>', '<p><strong>Locations de courte durée : les villes reprennent la main</strong></p><p>Dans de nombreuses villes françaises, les logements loués aux touristes pour quelques nuits se comptent par milliers. Pour les propriétaires, l''opération est rentable : un appartement loué à la nuit rapporte souvent deux à trois fois plus qu''une location classique. Mais les municipalités s''inquiètent, et plusieurs d''entre elles ont décidé de limiter ces locations à quatre-vingt-dix jours par an.</p><p>À Annecy, Claire Morel, infirmière, cherche un logement depuis huit mois. « Dans mon ancien immeuble, la moitié des appartements sont devenus des locations touristiques. Les propriétaires préfèrent louer à la semaine en été plutôt qu''à une famille toute l''année. » Comme elle, de nombreux salariés renoncent à vivre près de leur travail, faute de logements disponibles à un prix raisonnable.</p><p>Pour l''économiste Antoine Ravel, le lien est réel mais doit être nuancé. « Les locations touristiques ne sont pas la seule cause de la crise du logement. On construit trop peu, et les prix augmentent aussi dans des villes peu touristiques. Mais dans les quartiers anciens des centres, leur effet est indéniable : chaque appartement transformé est un logement de moins pour les habitants. »</p><p>Les propriétaires, eux, dénoncent une mesure injuste. Beaucoup expliquent que ces revenus leur permettent de rembourser un emprunt ou de compléter une petite retraite. Ils rappellent aussi que les touristes font vivre les commerces et les restaurants du centre, notamment hors saison.</p><p>Reste à faire respecter les règles. Faute de contrôleurs, de nombreuses villes peinent à repérer les annonces illégales. Certaines ont choisi de croiser les données des plateformes avec celles des impôts ; d''autres comptent sur les signalements des voisins. Sans moyens de contrôle, préviennent les associations de locataires, la limite de quatre-vingt-dix jours risque de rester une promesse sur le papier.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• rentable (adjectif) : có lãi\n• une municipalité : chính quyền thành phố\n• indéniable (adjectif) : không thể chối cãi\n• un emprunt : khoản vay\n• un signalement : sự báo cáo, tố giác","explications":"• Bài 1, 2 của đề B2: một bài báo có nhiều người được trích lời. Ghi tên từng người ra lề cùng ý chính của họ trước khi đọc câu hỏi.\n• Phương án sai thường phóng đại (« la principale cause », « aucun effet ») trong khi văn bản nói có chừng mực.","isPremium":true,"price":19000,"kyNang":"B2-CE-1","vong":"chot","thuTu":11}'::jsonb, '2026-11-14T20:00:08.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py01k', 'b2ce098qc072', 1, 'qcm', 'Pourquoi les propriétaires choisissent-ils la location de courte durée ?', '{"options":["Elle rapporte bien plus qu''une location à l''année.","Elle est encouragée par les municipalités touristiques.","Elle leur évite de payer des impôts sur leurs revenus."]}'::jsonb, '{"answer":0}'::jsonb, '« rapporte souvent deux à trois fois plus qu''une location classique ».'), ('qmwgmy8py01l', 'b2ce098qc072', 2, 'qcm', 'Quelle décision plusieurs villes ont-elles prise ?', '{"options":["Construire des logements réservés aux saisonniers.","Interdire toute location aux touristes étrangers.","Limiter le nombre de jours de location par an."]}'::jsonb, '{"answer":2}'::jsonb, '« limiter ces locations à quatre-vingt-dix jours par an ».'), ('qmwgmy8py01m', 'b2ce098qc072', 3, 'qcm', 'Le témoignage de Claire Morel illustre…', '{"options":["la difficulté des salariés à se loger.","la hausse du prix des loyers pour les étudiants.","les problèmes de bruit causés par les touristes."]}'::jsonb, '{"answer":0}'::jsonb, '« de nombreux salariés renoncent à vivre près de leur travail, faute de logements disponibles ».'), ('qmwgmy8py01n', 'b2ce098qc072', 4, 'qcm', 'Pour Antoine Ravel, les locations touristiques…', '{"options":["sont la principale cause de la crise du logement dans tout le pays.","pèsent surtout dans les quartiers anciens des centres.","n''ont aucun effet réel sur le marché du logement."]}'::jsonb, '{"answer":1}'::jsonb, '« dans les quartiers anciens des centres, leur effet est indéniable », nhưng « pas la seule cause ».'), ('qmwgmy8py01o', 'b2ce098qc072', 5, 'qcm', 'Selon lui, la crise du logement s''explique aussi par…', '{"options":["la baisse des salaires des infirmières.","l''arrivée de nombreux retraités.","une construction insuffisante."]}'::jsonb, '{"answer":2}'::jsonb, '« On construit trop peu ».'), ('qmwgmy8py01p', 'b2ce098qc072', 6, 'qcm', 'Quel argument économique les propriétaires avancent-ils ?', '{"options":["Les touristes font travailler les commerces locaux.","Les touristes paient plus d''impôts que les habitants.","Les locations créent des emplois de contrôleurs."]}'::jsonb, '{"answer":0}'::jsonb, '« les touristes font vivre les commerces et les restaurants du centre ».'), ('qmwgmy8py01q', 'b2ce098qc072', 7, 'qcm', 'Selon les associations de locataires, quel est le principal risque ?', '{"options":["Que la règle reste sans effet faute de contrôles.","Que les propriétaires quittent les centres-villes.","Que les voisins dénoncent des annonces légales."]}'::jsonb, '{"answer":0}'::jsonb, '« Sans moyens de contrôle… risque de rester une promesse sur le papier ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce108qd073', 'practice', 'Lecture B2 : entre les lignes', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions. Attention : certaines réponses ne sont pas écrites directement, il faut les déduire du texte.</p>', '<p><strong>Une banque qui se transforme</strong></p><p>La lettre est arrivée un lundi matin dans la boîte mail des quatre cents salariés de la banque régionale Duval. La direction y présente un grand projet de transformation, destiné à rapprocher la banque de ses clients. Les agences de six petites villes du département, explique-t-elle, seront regroupées dans un nouvel espace moderne au centre de la préfecture, ouvert jusqu''à vingt heures.</p><p>La lettre insiste longuement sur les nouveaux services en ligne : application repensée, conseiller joignable par vidéo, signature électronique des contrats. Elle précise que les clients des agences concernées n''auront plus à se déplacer pour la plupart de leurs opérations.</p><p>Le nombre de postes prévus dans le nouvel espace n''est pas mentionné. En revanche, la direction remercie chaleureusement les équipes pour leur capacité d''adaptation et annonce la création d''une cellule chargée d''étudier les projets professionnels de chacun. Des formations à d''autres métiers seront proposées à ceux qui le souhaitent.</p><p>Dans les agences, la lettre a été lue plusieurs fois. Au guichet de Saint-Aubin, Martine, quarante ans de maison, a simplement demandé à son responsable si le nouvel espace avait une place de parking pour les clients âgés. Il n''a pas su lui répondre.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• regrouper (verbe) : gộp lại\n• la préfecture : thủ phủ tỉnh\n• une cellule : nhóm phụ trách\n• quarante ans de maison : làm cho công ty bốn mươi năm\n• le guichet : quầy giao dịch","explications":"• Suy luận = dựa vào chi tiết CÓ trong bài để rút ra điều bài không nói thẳng. Không suy diễn quá xa.\n• Chú ý điều bị BỎ QUA (« n''est pas mentionné »): đó thường là ý ngầm của câu hỏi.","kyNang":"B2-CE-2","vong":"hoc","thuTu":1}'::jsonb, '2026-11-14T20:00:09.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py01r', 'b2ce108qd073', 1, 'qcm', 'Que comprend-on au sujet des agences des six petites villes ?', '{"options":["Elles vont être entièrement rénovées.","Elles vont fermer.","Elles vont ouvrir plus tard le soir."]}'::jsonb, '{"answer":1}'::jsonb, 'Chữ « regroupées dans un nouvel espace moderne au centre de la préfecture » là cách nói giảm: sáu chi nhánh nhỏ sẽ không còn.'), ('qmwgmy8py01s', 'b2ce108qd073', 2, 'qcm', 'Pourquoi la lettre insiste-t-elle sur les services en ligne ?', '{"options":["Pour présenter le changement comme un avantage pour les clients.","Pour annoncer la fin prochaine de l''application de la banque.","Pour demander aux salariés leur avis sur ces nouveaux outils."]}'::jsonb, '{"answer":0}'::jsonb, 'Lá thư biến việc đóng chi nhánh thành lợi ích: khách « n''auront plus à se déplacer pour la plupart de leurs opérations ».'), ('qmwgmy8py01t', 'b2ce108qd073', 3, 'qcm', 'Que laisse deviner l''absence d''information sur les postes ?', '{"options":["La direction n''a pas encore choisi le lieu.","Des emplois pourraient disparaître.","Le nouvel espace va recruter massivement."]}'::jsonb, '{"answer":1}'::jsonb, 'Điều không nói cũng là thông tin: « Le nombre de postes prévus dans le nouvel espace n''est pas mentionné ».'), ('qmwgmy8py01u', 'b2ce108qd073', 4, 'qcm', 'La cellule chargée des projets professionnels suggère que…', '{"options":["les clients pourront demander des conseils sur leur carrière.","certains salariés devront changer de métier ou partir.","tous les salariés recevront une prime de fin d''année."]}'::jsonb, '{"answer":1}'::jsonb, '« étudier les projets professionnels de chacun » và « formations à d''autres métiers »: có người sẽ không giữ được việc cũ.'), ('qmwgmy8py01v', 'b2ce108qd073', 5, 'qcm', 'Que révèle la question de Martine ?', '{"options":["Elle souhaite obtenir une place de parking pour elle-même.","Elle doute que le nouvel espace convienne aux clients âgés.","Elle veut être la première à travailler dans le nouvel espace."]}'::jsonb, '{"answer":1}'::jsonb, 'Bà nghĩ tới khách lớn tuổi không dùng mạng và phải đi xa: « une place de parking pour les clients âgés ».'), ('qmwgmy8py01w', 'b2ce108qd073', 6, 'qcm', 'Quel est le ton de l''auteur de ce texte ?', '{"options":["Purement technique.","Franchement enthousiaste.","Discrètement critique."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả không phán xét thẳng nhưng chọn chi tiết để người đọc tự hiểu, kết bằng « Il n''a pas su lui répondre ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce118qd074', 'practice', 'Lecture B2 : l''auteur est-il convaincu ?', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions. Attention : certaines réponses ne sont pas écrites directement, il faut les déduire du texte.</p>', '<p><strong>La ville intelligente, vraiment ?</strong></p><p>Depuis un an, notre ville se veut intelligente. Des capteurs mesurent le passage des voitures, les lampadaires baissent d''intensité quand la rue est vide, et une application permet de signaler un trou dans la chaussée. Sur le papier, tout cela est séduisant, et je reconnais volontiers que l''éclairage public consomme moins d''énergie qu''avant.</p><p>Mais j''ai voulu tester l''application. J''ai signalé un trou devant l''école de mon quartier, photo à l''appui. Trois semaines plus tard, j''ai reçu un message automatique me remerciant pour ma participation citoyenne. Le trou, lui, est toujours là ; il s''est même agrandi, sans doute pour mieux être repéré par les capteurs.</p><p>La mairie annonce fièrement que plus de dix mille signalements ont été envoyés. On aimerait savoir combien ont été traités. Collecter des données n''a jamais réparé une route : il faut ensuite des agents, du matériel et un budget, c''est-à-dire tout ce que la technologie ne fournit pas.</p><p>Je ne suis pas opposé au progrès. Je constate simplement qu''une ville vraiment intelligente serait d''abord une ville qui écoute, puis qui agit. Pour l''instant, la nôtre écoute très bien.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un capteur : cảm biến\n• la chaussée : mặt đường\n• séduisant (adjectif) : hấp dẫn\n• photo à l''appui : có ảnh làm bằng chứng\n• un signalement : lượt báo cáo","explications":"• Thái độ tác giả lộ qua từ đánh giá (« séduisant », « fièrement ») và qua giọng mỉa mai: câu khen mà nội dung lại chê.\n• Câu nhượng bộ (« Je ne suis pas opposé au progrès ») chưa phải ý chính: ý chính nằm sau « Je constate simplement ».","kyNang":"B2-CE-2","vong":"hoc","thuTu":2}'::jsonb, '2026-11-14T20:00:10.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py01x', 'b2ce118qd074', 1, 'qcm', 'Dans le premier paragraphe, l''auteur…', '{"options":["affirme que les capteurs ne fonctionnent pas.","regrette l''arrivée des lampadaires modernes.","reconnaît un avantage réel du projet."]}'::jsonb, '{"answer":2}'::jsonb, '« je reconnais volontiers que l''éclairage public consomme moins d''énergie qu''avant ».'), ('qmwgmy8py01y', 'b2ce118qd074', 2, 'qcm', 'Quelle est son attitude quand il parle du trou qui s''agrandit ?', '{"options":["Ironique.","Indifférente.","Admirative."]}'::jsonb, '{"answer":0}'::jsonb, 'Câu « sans doute pour mieux être repéré par les capteurs » là mỉa mai: cái hố to ra không phải để được phát hiện.'), ('qmwgmy8py01z', 'b2ce118qd074', 3, 'qcm', 'Que montre le message automatique reçu par l''auteur ?', '{"options":["Son signalement a été enregistré mais pas traité.","L''application ne reçoit pas les photos envoyées.","La mairie a réparé la route très rapidement."]}'::jsonb, '{"answer":0}'::jsonb, 'Có tin nhắn cảm ơn, nhưng « Le trou, lui, est toujours là ».'), ('qmwgmy8py020', 'b2ce118qd074', 4, 'qcm', 'Que pense l''auteur du chiffre annoncé par la mairie ?', '{"options":["Il est sans doute plus élevé en réalité.","Il montre que les habitants aiment leur ville.","Il ne prouve pas que les problèmes sont réglés."]}'::jsonb, '{"answer":2}'::jsonb, '« On aimerait savoir combien ont été traités »: số lượt báo không nói lên số việc đã làm.'), ('qmwgmy8py021', 'b2ce118qd074', 5, 'qcm', 'Selon l''auteur, qu''est-ce qui manque au projet ?', '{"options":["Les moyens humains et financiers pour agir.","Un plus grand nombre de capteurs dans les rues.","Une meilleure application pour les signalements."]}'::jsonb, '{"answer":0}'::jsonb, '« il faut ensuite des agents, du matériel et un budget ».'), ('qmwgmy8py022', 'b2ce118qd074', 6, 'qcm', 'Que signifie la dernière phrase ?', '{"options":["La ville recueille les plaintes mais n''agit pas.","Les habitants n''utilisent pas assez l''application.","La ville est attentive et règle tous les problèmes."]}'::jsonb, '{"answer":0}'::jsonb, 'Ngay trước đó: thành phố thông minh phải « une ville qui écoute, puis qui agit ». « Pour l''instant, la nôtre écoute très bien » nghĩa là chỉ nghe, chưa làm.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce128qd075', 'practice', 'Lecture B2 : pourquoi écrit-il cela ?', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions. Attention : certaines réponses ne sont pas écrites directement, il faut les déduire du texte.</p>', '<p><strong>Apprendre à s''ennuyer</strong></p><p>Dans le train, la salle d''attente ou la file du supermarché, un même geste : sortir son téléphone. Nous ne supportons plus le moindre temps mort. Pourtant, plusieurs chercheurs en psychologie s''intéressent aujourd''hui aux vertus de l''ennui.</p><p>Leurs expériences sont parfois surprenantes. Dans l''une d''elles, des volontaires devaient d''abord recopier des numéros de téléphone pendant un quart d''heure, une tâche volontairement fastidieuse. On leur demandait ensuite de trouver le plus d''usages possibles pour deux gobelets en plastique. Ceux qui s''étaient ennuyés ont proposé des idées plus nombreuses et plus originales que les autres.</p><p>L''explication tient en partie au fonctionnement du cerveau : quand rien ne retient notre attention, l''esprit vagabonde, fait des liens inattendus, revient sur des souvenirs. C''est souvent dans ces moments que surgissent les idées. Plus d''un écrivain raconte avoir trouvé le début d''un roman en regardant la pluie tomber.</p><p>Il ne s''agit pas de faire l''éloge de l''ennui permanent, qui peut être le signe d''un malaise. Mais apprendre aux enfants à rester un moment sans écran, sans activité programmée, c''est peut-être leur offrir un espace où naît l''imagination. Les parents qui remplissent chaque mercredi de cours et d''ateliers devraient peut-être y penser.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un temps mort : khoảng thời gian trống\n• fastidieux (adjectif) : nhàm chán, tẻ nhạt\n• vagabonder (verbe) : lang thang, (ý nghĩ) trôi đi\n• surgir (verbe) : bất chợt xuất hiện\n• faire l''éloge de : ca ngợi","explications":"• Câu « Pourquoi l''auteur cite-t-il… ? » hỏi CHỨC NĂNG của chi tiết: ví dụ, bằng chứng, rào đón, hay lời khuyên. Tìm câu ý chính mà chi tiết đó minh hoạ.\n• Phương án sai thường lấy chữ trong chính chi tiết (« gobelets », « écrivains ») nhưng gán sai mục đích.","isPremium":true,"price":19000,"kyNang":"B2-CE-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-14T20:00:11.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py023', 'b2ce128qd075', 1, 'qcm', 'Pourquoi l''auteur commence-t-il par des scènes de la vie quotidienne ?', '{"options":["Pour présenter les résultats d''une étude sur les écrans.","Pour critiquer la mauvaise qualité des transports publics.","Pour que le lecteur se reconnaisse dans ce comportement."]}'::jsonb, '{"answer":2}'::jsonb, 'Ai cũng từng thấy « un même geste : sortir son téléphone »: người đọc tự nhận ra mình.'), ('qmwgmy8py024', 'b2ce128qd075', 2, 'qcm', 'Pourquoi l''expérience des numéros de téléphone est-elle citée ?', '{"options":["Pour montrer que l''ennui peut favoriser la créativité.","Pour expliquer comment recycler les gobelets en plastique.","Pour prouver que les gens ont une mauvaise mémoire."]}'::jsonb, '{"answer":0}'::jsonb, 'Người đã chán đưa ra « des idées plus nombreuses et plus originales ».'), ('qmwgmy8py025', 'b2ce128qd075', 3, 'qcm', 'Pourquoi la première tâche était-elle volontairement fastidieuse ?', '{"options":["Pour sélectionner les volontaires les plus patients.","Pour provoquer l''ennui chez les volontaires.","Pour vérifier qu''ils savaient bien écrire les chiffres."]}'::jsonb, '{"answer":1}'::jsonb, 'Thí nghiệm cần người tham gia chán trước: « une tâche volontairement fastidieuse ».'), ('qmwgmy8py026', 'b2ce128qd075', 4, 'qcm', 'Pourquoi l''auteur parle-t-il des écrivains ?', '{"options":["Pour montrer que les écrivains s''ennuient souvent.","Pour conseiller la lecture de romans aux enfants qui s''ennuient le mercredi.","Pour illustrer qu''une idée peut naître d''un moment vide."]}'::jsonb, '{"answer":2}'::jsonb, '« trouvé le début d''un roman en regardant la pluie tomber » minh hoạ cho câu « C''est souvent dans ces moments que surgissent les idées ».'), ('qmwgmy8py027', 'b2ce128qd075', 5, 'qcm', 'Pourquoi l''auteur précise-t-il que l''ennui permanent peut être un malaise ?', '{"options":["Pour éviter qu''on déforme sa pensée.","Pour conseiller de consulter un médecin.","Pour contredire les chercheurs cités."]}'::jsonb, '{"answer":0}'::jsonb, 'Tác giả rào trước: « Il ne s''agit pas de faire l''éloge de l''ennui permanent ».'), ('qmwgmy8py028', 'b2ce128qd075', 6, 'qcm', 'À qui s''adresse indirectement la dernière phrase ?', '{"options":["Aux enfants qui passent trop de temps devant un écran.","Aux enseignants qui donnent trop de devoirs le mercredi.","Aux parents qui chargent l''emploi du temps des enfants."]}'::jsonb, '{"answer":2}'::jsonb, '« Les parents qui remplissent chaque mercredi de cours et d''ateliers devraient peut-être y penser ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce138qd076', 'practice', 'Lecture B2 : vrai, mais pas dans le texte', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions. Attention : répondez uniquement d''après le texte, même si une autre réponse vous paraît vraie dans la réalité.</p>', '<p><strong>Le loup, un retour qui divise</strong></p><p>Disparu de France dans les années 1930, le loup est revenu naturellement par les Alpes au début des années 1990, depuis l''Italie. Aujourd''hui, on estime sa population à plus d''un millier d''individus, et il a été observé jusque dans des régions où personne ne l''attendait.</p><p>Pour les éleveurs de moutons, ce retour est vécu comme une épreuve. Les attaques se comptent par milliers chaque année, et les clôtures électriques, les chiens de protection et les bergers supplémentaires ont un coût que les aides publiques ne couvrent pas entièrement. Au-delà de l''argent, beaucoup évoquent la fatigue de nuits passées à surveiller le troupeau.</p><p>Les naturalistes rappellent que le loup joue un rôle dans les écosystèmes : en chassant cerfs et chevreuils, il limite leur nombre et permet aux jeunes arbres de repousser. Mais ils admettent que cet effet, bien documenté dans de grands espaces sauvages, est plus difficile à mesurer dans les paysages français, façonnés par l''homme.</p><p>Entre ces deux mondes, l''État tente de tenir un équilibre : l''espèce reste protégée, mais un certain nombre de loups peuvent être abattus chaque année lorsque les attaques se répètent. Une solution qui ne satisfait vraiment personne.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un éleveur : người chăn nuôi\n• un troupeau : đàn (gia súc)\n• un chevreuil : hoẵng\n• façonner (verbe) : nhào nặn, định hình\n• abattre (verbe) : bắn hạ","explications":"• Bẫy kiến thức nền: phương án đúng ngoài đời nhưng bài KHÔNG nói. Với mỗi phương án, hỏi: câu nào trong bài chứng minh?\n• Câu hỏi có « Selon le texte », « D''après le texte » là lời nhắc: chỉ dựa vào bài.","isPremium":true,"price":19000,"kyNang":"B2-CE-2","vong":"hoc","thuTu":4}'::jsonb, '2026-11-14T20:00:12.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py029', 'b2ce138qd076', 1, 'qcm', 'Selon le texte, comment le loup est-il revenu en France ?', '{"options":["Il a été réintroduit par des associations.","Naturellement, en venant d''Italie.","Il est arrivé d''Espagne par les Pyrénées."]}'::jsonb, '{"answer":1}'::jsonb, '« revenu naturellement par les Alpes… depuis l''Italie ». Bài không nhắc Tây Ban Nha hay việc thả lại.'), ('qmwgmy8py02a', 'b2ce138qd076', 2, 'qcm', 'D''après le texte, quelle difficulté les éleveurs rencontrent-ils ?', '{"options":["La baisse du prix de la viande d''agneau.","Le coût de la protection des troupeaux.","Le manque de jeunes qui veulent devenir bergers."]}'::jsonb, '{"answer":1}'::jsonb, '« ont un coût que les aides publiques ne couvrent pas entièrement ». Hai phương án kia có thể đúng ngoài đời nhưng bài không nói.'), ('qmwgmy8py02b', 'b2ce138qd076', 3, 'qcm', 'Au-delà de l''argent, de quoi parlent beaucoup d''éleveurs ?', '{"options":["De la fatigue liée à la surveillance nocturne.","De la colère des touristes en montagne.","De leur peur d''être eux-mêmes attaqués en montagne par les loups."]}'::jsonb, '{"answer":0}'::jsonb, '« la fatigue de nuits passées à surveiller le troupeau ».'), ('qmwgmy8py02c', 'b2ce138qd076', 4, 'qcm', 'Selon les naturalistes, le loup…', '{"options":["chasse surtout les sangliers et les lapins.","évite toujours de s''approcher des villages.","aide la forêt à se renouveler."]}'::jsonb, '{"answer":2}'::jsonb, 'Sói săn hươu nai nên « permet aux jeunes arbres de repousser ». Bài không nói lợn rừng hay làng mạc.'), ('qmwgmy8py02d', 'b2ce138qd076', 5, 'qcm', 'Que reconnaissent les naturalistes ?', '{"options":["Cet effet est difficile à mesurer en France.","Le loup n''a aucun rôle utile dans la nature.","Le loup a disparu des grands parcs sauvages."]}'::jsonb, '{"answer":0}'::jsonb, '« plus difficile à mesurer dans les paysages français, façonnés par l''homme ».'), ('qmwgmy8py02e', 'b2ce138qd076', 6, 'qcm', 'Selon le texte, que permet la règle actuelle ?', '{"options":["De rembourser entièrement les pertes des éleveurs.","De chasser le loup librement pendant toute l''année.","D''abattre certains loups après des attaques répétées."]}'::jsonb, '{"answer":2}'::jsonb, '« un certain nombre de loups peuvent être abattus chaque année lorsque les attaques se répètent ». Việc bồi hoàn đầy đủ trái với đoạn 2.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce148qd077', 'practice', 'Lecture B2 : une tribune sur l''université', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions. Attention : certaines réponses ne sont pas écrites directement, il faut les déduire du texte.</p>', '<p><strong>L''université n''est pas une usine à diplômes</strong></p><p><em>Tribune d''Hélène Vasseur, professeure de philosophie</em></p><p>Chaque année, à la rentrée, on me pose la même question : à quoi sert un diplôme de philosophie ? Sous-entendu : à quel métier mène-t-il, et combien rapporte-t-il ? La question est légitime ; les étudiants et leurs familles investissent du temps et de l''argent. Mais elle révèle une vision de l''université que je crois dangereuse.</p><p>Depuis quelques années, les formations sont évaluées selon le taux d''insertion professionnelle de leurs diplômés, mesuré six mois après la fin des études. Les filières qui affichent de bons chiffres reçoivent des moyens supplémentaires ; les autres doivent se justifier. Je n''ai rien contre les chiffres. Je me demande seulement ce qu''on aurait pensé, six mois après leur diplôme, de bien des chercheurs dont les travaux ont changé notre vie des décennies plus tard.</p><p>L''université n''a jamais eu pour seule mission de préparer à un emploi. Elle forme des citoyens capables de lire un texte difficile, de douter d''une information, d''argumenter face à quelqu''un qui ne pense pas comme eux. Ces compétences ne figurent dans aucun tableau d''indicateurs ; elles sont pourtant celles dont une démocratie a le plus besoin.</p><p>On me répondra que les étudiants doivent bien vivre. C''est vrai, et c''est pourquoi il faut des stages, des liens avec les entreprises, une orientation plus honnête. Mais réduire la valeur d''une formation à un salaire de sortie, c''est oublier que les métiers de demain n''existent pas encore, et que la capacité d''apprendre comptera plus que tout savoir figé.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une tribune : bài viết quan điểm\n• sous-entendu : hàm ý là\n• l''insertion professionnelle : việc có việc làm sau khi học\n• une filière : ngành học\n• figé (adjectif) : cứng nhắc, bất biến","explications":"• Trong xã luận, tác giả hay nhượng bộ trước (« La question est légitime », « C''est vrai ») rồi mới phản bác bằng « Mais ». Ý thật nằm sau « Mais ».\n• Câu « On me répondra que… » báo hiệu tác giả đoán trước phản biện để bác nó.","isPremium":true,"price":19000,"kyNang":"B2-CE-2","vong":"hoc","thuTu":5}'::jsonb, '2026-11-14T20:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py02f', 'b2ce148qd077', 1, 'qcm', 'Que sous-entend la question qu''on pose chaque année à l''auteure ?', '{"options":["Que la philosophie mène difficilement à un emploi.","Que les cours de philosophie sont trop difficiles.","Que l''université devrait coûter moins cher."]}'::jsonb, '{"answer":0}'::jsonb, 'Chính tác giả giải mã: « Sous-entendu : à quel métier mène-t-il, et combien rapporte-t-il ? »'), ('qmwgmy8py02g', 'b2ce148qd077', 2, 'qcm', 'Que pense l''auteure de cette question ?', '{"options":["Elle l''accepte car elle partage cette vision.","Elle la trouve ridicule et refuse d''y répondre.","Elle la comprend mais en rejette la vision."]}'::jsonb, '{"answer":2}'::jsonb, '« La question est légitime » nhưng « une vision de l''université que je crois dangereuse ».'), ('qmwgmy8py02h', 'b2ce148qd077', 3, 'qcm', 'Avec l''exemple des chercheurs, l''auteure suggère que…', '{"options":["la valeur d''une formation peut apparaître très tard.","les statistiques sur l''emploi sont souvent fausses.","les chercheurs trouvent rapidement un emploi bien payé."]}'::jsonb, '{"answer":0}'::jsonb, 'Sáu tháng sau tốt nghiệp chưa thấy gì, nhưng công trình của họ thay đổi cuộc sống « des décennies plus tard ».'), ('qmwgmy8py02i', 'b2ce148qd077', 4, 'qcm', 'Quand elle écrit qu''elle n''a rien contre les chiffres, l''auteure…', '{"options":["écarte un reproche avant de critiquer la méthode.","approuve totalement le système d''évaluation actuel.","avoue qu''elle préfère les sciences à la philosophie."]}'::jsonb, '{"answer":0}'::jsonb, 'Câu rào đón, rồi phản biện ngay sau đó: « Je me demande seulement ce qu''on aurait pensé ».'), ('qmwgmy8py02j', 'b2ce148qd077', 5, 'qcm', 'Selon elle, quelles compétences l''université développe-t-elle ?', '{"options":["La maîtrise des logiciels et des langues.","La gestion d''entreprise et la vente.","L''esprit critique et l''argumentation."]}'::jsonb, '{"answer":2}'::jsonb, '« de douter d''une information, d''argumenter face à quelqu''un qui ne pense pas comme eux ».'), ('qmwgmy8py02k', 'b2ce148qd077', 6, 'qcm', 'Pourquoi évoque-t-elle les métiers de demain ?', '{"options":["Pour annoncer la création de nouvelles formations.","Pour montrer que savoir apprendre comptera davantage.","Pour encourager les étudiants à choisir l''informatique."]}'::jsonb, '{"answer":1}'::jsonb, '« la capacité d''apprendre comptera plus que tout savoir figé ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce158qd078', 'practice', 'Lecture B2 : une chronique', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions. Attention : certaines réponses ne sont pas écrites directement, il faut les déduire du texte.</p>', '<p><strong>La queue, nouveau luxe</strong></p><p>Il y a, dans mon quartier, une boulangerie devant laquelle on fait la queue quarante minutes le samedi matin. Je l''ai découvert par hasard, en passant à huit heures et demie : une file d''une trentaine de personnes, calmes, téléphone à la main, comme devant l''entrée d''un concert.</p><p>J''ai donc rejoint la file, par curiosité professionnelle. Devant moi, un couple filmait l''attente pour ses amis en direct. Derrière moi, une jeune femme m''a confié qu''elle venait de l''autre bout de la ville. Pour le pain ? Non, pour la brioche à la pistache, vue sur les réseaux.</p><p>La brioche était bonne. Pas meilleure, me semble-t-il, que celle de la boulangerie d''en face, où personne n''attend et où la vendeuse connaît le prénom de ses clients. Mais celle d''en face n''a pas de vitrine en marbre, ni de sac en papier kraft orné d''un logo minimaliste.</p><p>Je ne me moque pas : j''ai fait la queue moi aussi, et j''ai posté une photo. C''est peut-être cela qu''on achète, au fond : moins une brioche qu''une histoire à raconter. Le samedi suivant, je suis retourné en face. La vendeuse m''a demandé si j''avais été malade.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• faire la queue : xếp hàng\n• par curiosité : vì tò mò\n• confier (verbe) : tâm sự\n• d''en face : ở phía đối diện\n• orné de : được trang trí bằng","explications":"• Chronique (tạp bút) hay hài hước, nói bóng gió. Đừng hiểu từng chữ: câu « La vendeuse m''a demandé si j''avais été malade » nói về sự quen thuộc, không về bệnh.\n• Người viết tự giễu mình (« Je ne me moque pas ») để người đọc dễ đồng tình.","isPremium":true,"price":19000,"kyNang":"B2-CE-2","vong":"on","thuTu":6}'::jsonb, '2026-11-14T20:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py02l', 'b2ce158qd078', 1, 'qcm', 'Pourquoi l''auteur compare-t-il la file à l''entrée d''un concert ?', '{"options":["Pour montrer que les clients sont bruyants et agités.","Pour souligner que l''attente est devenue un événement.","Pour expliquer que la boulangerie organise des concerts."]}'::jsonb, '{"answer":1}'::jsonb, '« comme devant l''entrée d''un concert »: xếp hàng mua bánh thành một sự kiện.'), ('qmwgmy8py02m', 'b2ce158qd078', 2, 'qcm', 'Qu''est-ce qui attire la jeune femme dans cette boulangerie ?', '{"options":["Un produit vu sur internet.","L''accueil de la vendeuse.","Le prix très bas du pain."]}'::jsonb, '{"answer":0}'::jsonb, '« pour la brioche à la pistache, vue sur les réseaux ».'), ('qmwgmy8py02n', 'b2ce158qd078', 3, 'qcm', 'Que pense l''auteur de la brioche ?', '{"options":["Elle est de loin la meilleure de toute la ville.","Elle est trop chère pour sa qualité.","Elle n''est pas supérieure à celle d''en face."]}'::jsonb, '{"answer":2}'::jsonb, '« Pas meilleure, me semble-t-il, que celle de la boulangerie d''en face ».'), ('qmwgmy8py02o', 'b2ce158qd078', 4, 'qcm', 'En décrivant la vitrine et le sac, l''auteur suggère que…', '{"options":["les clients aiment acheter des sacs écologiques.","la boulangerie d''en face devrait fermer bientôt.","le succès tient surtout à l''image du magasin."]}'::jsonb, '{"answer":2}'::jsonb, 'Khác biệt nằm ở vẻ ngoài: « vitrine en marbre », « un logo minimaliste », không phải ở bánh.'), ('qmwgmy8py02p', 'b2ce158qd078', 5, 'qcm', 'Quand l''auteur écrit qu''il ne se moque pas, il…', '{"options":["affirme qu''il n''a jamais fait la queue.","reconnaît qu''il a lui-même suivi la mode.","critique sévèrement les autres clients."]}'::jsonb, '{"answer":1}'::jsonb, '« j''ai fait la queue moi aussi, et j''ai posté une photo ».'), ('qmwgmy8py02q', 'b2ce158qd078', 6, 'qcm', 'Que montre la question de la vendeuse à la fin ?', '{"options":["La vendeuse s''inquiète pour la santé de tous les habitants du quartier.","L''absence de l''auteur, client fidèle, a été remarquée.","L''auteur a vraiment été malade après la brioche."]}'::jsonb, '{"answer":1}'::jsonb, 'Bà bán hàng tưởng ông ốm vì tuần trước ông không đến: « si j''avais été malade ». Ông là khách quen.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce168qd079', 'practice', 'Lecture B2 : un éditorial sur la presse', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions. Attention : certaines réponses ne sont pas écrites directement, il faut les déduire du texte.</p>', '<p><strong>Payer pour s''informer</strong></p><p><em>Éditorial</em></p><p>Nous avons tous pris une mauvaise habitude : celle de considérer l''information comme gratuite. Pendant des années, les journaux ont mis leurs articles en ligne sans rien demander, en espérant que la publicité suffirait à les financer. Elle n''a pas suffi.</p><p>Pendant ce temps, les recettes publicitaires sont parties vers les grandes plateformes, qui diffusent nos articles sans les avoir produits. Une enquête sérieuse peut demander des mois de travail, des déplacements, parfois des avocats. Un message viral, lui, ne coûte rien à écrire ; il peut même rapporter beaucoup à celui qui l''invente.</p><p>On nous reproche parfois de cacher nos articles derrière un abonnement. Je comprends l''agacement de ceux qui tombent sur un article bloqué. Mais demandons-nous ce qu''il advient d''une démocratie dans laquelle seule l''information qui ne coûte rien circule librement.</p><p>Il ne s''agit pas de culpabiliser nos lecteurs, sans qui ce journal n''existerait pas. Il s''agit de rappeler une évidence que nous avons nous-mêmes contribué à faire oublier : une information fiable a un prix. La question est seulement de savoir qui le paie, et ce qu''il attend en échange.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un éditorial : bài xã luận\n• les recettes (nom féminin) : doanh thu\n• viral (adjectif) : lan truyền nhanh\n• l''agacement (nom masculin) : sự bực mình\n• culpabiliser (verbe) : làm cho thấy có lỗi","explications":"• Xã luận hay kết bằng câu mở: hãy hỏi « nếu… thì sao? » để tìm ý ngầm (« qui le paie, et ce qu''il attend en échange »).\n• Câu hỏi tu từ « demandons-nous ce qu''il advient… » là một lời cảnh báo.","isPremium":true,"price":19000,"kyNang":"B2-CE-2","vong":"on","thuTu":7}'::jsonb, '2026-11-14T20:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py02r', 'b2ce168qd079', 1, 'qcm', 'Dans le premier paragraphe, l''auteur reconnaît que…', '{"options":["la publicité a parfaitement financé les journaux en ligne.","les lecteurs ont toujours refusé de payer pour s''informer.","les journaux ont eux-mêmes habitué le public à la gratuité."]}'::jsonb, '{"answer":2}'::jsonb, '« les journaux ont mis leurs articles en ligne sans rien demander »; cuối bài nhắc lại « que nous avons nous-mêmes contribué à faire oublier ».'), ('qmwgmy8py02s', 'b2ce168qd079', 2, 'qcm', 'Que reproche-t-il aux grandes plateformes ?', '{"options":["De profiter d''articles qu''elles n''ont pas produits.","De demander trop d''argent aux lecteurs.","De refuser de publier les articles des journaux."]}'::jsonb, '{"answer":0}'::jsonb, '« qui diffusent nos articles sans les avoir produits ».'), ('qmwgmy8py02t', 'b2ce168qd079', 3, 'qcm', 'Pourquoi compare-t-il une enquête et un message viral ?', '{"options":["Pour reprocher aux journalistes leur manque de travail.","Pour montrer que l''information douteuse est plus rentable.","Pour expliquer comment écrire un bon article en ligne."]}'::jsonb, '{"answer":1}'::jsonb, 'Điều tra tốn kém, còn tin lan truyền « ne coûte rien à écrire ; il peut même rapporter beaucoup à celui qui l''invente ».'), ('qmwgmy8py02u', 'b2ce168qd079', 4, 'qcm', 'Quelle attitude adopte-t-il face aux critiques sur les abonnements ?', '{"options":["Il promet de supprimer les abonnements.","Il les rejette en accusant ses lecteurs d''être égoïstes.","Il les comprend tout en défendant son choix."]}'::jsonb, '{"answer":2}'::jsonb, '« Je comprends l''agacement » rồi « Mais demandons-nous ».'), ('qmwgmy8py02v', 'b2ce168qd079', 5, 'qcm', 'Quelle menace la question du troisième paragraphe suggère-t-elle ?', '{"options":["Une démocratie où domineraient des informations peu fiables.","La disparition complète de la publicité dans tous les journaux du pays.","Une hausse importante du prix des abonnements."]}'::jsonb, '{"answer":0}'::jsonb, '« seule l''information qui ne coûte rien circule librement »: tức là tin không ai trả tiền làm, khó tin cậy.'), ('qmwgmy8py02w', 'b2ce168qd079', 6, 'qcm', 'Que laisse entendre la dernière phrase ?', '{"options":["D''autres financeurs pourraient vouloir influencer l''information.","Les lecteurs paieront bientôt leur abonnement beaucoup moins cher qu''aujourd''hui.","Le journal va être racheté par une grande plateforme."]}'::jsonb, '{"answer":0}'::jsonb, '« qui le paie, et ce qu''il attend en échange »: nếu độc giả không trả, người trả tiền khác sẽ đòi điều gì đó.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce178qd07a', 'practice', 'Lecture B2 : sept questions d''inférence', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions. Attention : certaines réponses ne sont pas écrites directement, il faut les déduire du texte.</p>', '<p><strong>À Montclar, le cinéma tient bon</strong></p><p>Le Rex n''a que cent vingt fauteuils, dont une dizaine grincent de façon inquiétante. Depuis trente ans, c''est Bernard Lafont qui choisit les films, vend les billets et, quand il le faut, répare le projecteur. Il ne prend jamais de vacances en août : « C''est le seul mois où il y a du monde. »</p><p>Quand les plateformes de streaming sont arrivées, beaucoup lui ont prédit une fin rapide. Le Rex a perdu des spectateurs, c''est vrai, surtout parmi les jeunes. Mais il a aussi trouvé un nouveau public : des retraités qui viennent en groupe l''après-midi, des écoles des villages voisins, et même quelques adolescents depuis que Bernard organise une soirée par mois où ce sont eux qui choisissent le film.</p><p>La mairie verse une subvention chaque année. Le maire en parle avec fierté, mais rappelle aussi que le budget de la commune est serré et que tout se discute. Bernard, lui, a appris à ne pas trop compter dessus : il a déjà repeint la façade avec des bénévoles et lancé une collecte pour changer les fauteuils.</p><p>Ce qu''il défend, dit-il, ce n''est pas seulement le cinéma. C''est l''idée qu''un village a besoin d''endroits où l''on se retrouve sans rien avoir à acheter d''autre qu''un billet. Après chaque séance du jeudi, une partie du public reste dans le hall pour discuter du film. Certains, avoue-t-il en souriant, ne l''ont pas vraiment regardé.</p><p>Bernard aura soixante-dix ans l''an prochain. Il ne parle pas de retraite. Quand on lui demande qui reprendra le Rex, il montre la jeune femme qui tient la caisse le samedi : « Elle connaît déjà tous les films par cœur. »</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• grincer (verbe) : kêu cót két\n• prédire (verbe) : tiên đoán\n• une subvention : tiền trợ cấp\n• une collecte : cuộc quyên góp\n• reprendre (verbe) : tiếp quản","explications":"• Bài trộn đủ loại suy luận: ý ngầm, thái độ, mục đích chi tiết, bẫy kiến thức nền. Với mỗi câu, xác định trước nó thuộc loại nào.\n• Câu trích lời ngắn của nhân vật (« tout se discute ») thường là chìa khoá ý ngầm: đọc câu ngay trước nó.","isPremium":true,"price":19000,"kyNang":"B2-CE-2","vong":"chot","thuTu":8}'::jsonb, '2026-11-14T20:00:16.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8py02x', 'b2ce178qd07a', 1, 'qcm', 'Que suggère la remarque de Bernard sur le mois d''août ?', '{"options":["Les touristes n''aiment pas aller au cinéma.","Le reste de l''année, la salle est souvent peu remplie.","Il préfère partir en vacances pendant l''hiver, quand la montagne est plus calme."]}'::jsonb, '{"answer":1}'::jsonb, '« C''est le seul mois où il y a du monde »: các tháng khác vắng.'), ('qmwgmy8py02y', 'b2ce178qd07a', 2, 'qcm', 'Comment le Rex est-il présenté au début de l''article ?', '{"options":["Comme une salle modeste qui tient grâce à un homme.","Comme un cinéma moderne qui vient d''être rénové.","Comme une salle gérée par une grande entreprise."]}'::jsonb, '{"answer":0}'::jsonb, 'Ghế « grincent de façon inquiétante » và một mình Bernard làm mọi việc.'), ('qmwgmy8py02z', 'b2ce178qd07a', 3, 'qcm', 'Pourquoi l''auteur mentionne-t-il la soirée des adolescents ?', '{"options":["Pour montrer comment Bernard a regagné un public perdu.","Pour critiquer les goûts des jeunes en matière de films.","Pour annoncer que le cinéma sera réservé aux jeunes."]}'::jsonb, '{"answer":0}'::jsonb, 'Rạp mất khán giả trẻ, nhưng có lại vài em « depuis que Bernard organise une soirée par mois où ce sont eux qui choisissent le film ».'), ('qmwgmy8py030', 'b2ce178qd07a', 4, 'qcm', 'Que laisse entendre le maire quand il dit que tout se discute ?', '{"options":["Le maire veut choisir les films projetés.","Le cinéma recevra bientôt plus d''argent.","La subvention pourrait un jour être réduite."]}'::jsonb, '{"answer":2}'::jsonb, 'Ông nhắc « que le budget de la commune est serré »: khoản trợ cấp không chắc chắn.'), ('qmwgmy8py031', 'b2ce178qd07a', 5, 'qcm', 'D''après le texte, pourquoi Bernard a-t-il lancé une collecte ?', '{"options":["Les plateformes refusent de l''aider financièrement.","Il ne veut pas dépendre seulement de la mairie.","Le cinéma doit fermer à la fin de l''année."]}'::jsonb, '{"answer":1}'::jsonb, '« a appris à ne pas trop compter dessus », nên tự quyên góp và sơn lại với tình nguyện viên.'), ('qmwgmy8py032', 'b2ce178qd07a', 6, 'qcm', 'Que veut dire Bernard quand il dit que certains n''ont pas vraiment regardé le film ?', '{"options":["Ils trouvent les films choisis trop difficiles.","Ils s''endorment parce que les fauteuils sont confortables.","Ils viennent surtout pour retrouver les autres."]}'::jsonb, '{"answer":2}'::jsonb, 'Ông bảo vệ nơi gặp gỡ; sau suất chiếu « une partie du public reste dans le hall pour discuter ».'), ('qmwgmy8py033', 'b2ce178qd07a', 7, 'qcm', 'Que comprend-on à la fin de l''article ?', '{"options":["Bernard va prendre sa retraite l''an prochain et fermer la salle.","Bernard a peut-être déjà trouvé qui lui succédera.","La caissière veut ouvrir son propre cinéma."]}'::jsonb, '{"answer":1}'::jsonb, 'Hỏi ai tiếp quản, ông chỉ cô thu ngân: « Elle connaît déjà tous les films par cœur ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce188qd07b', 'practice', 'Lecture B2 : qui pense quoi ?', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez l''opinion de ces trois personnes sur un forum francophone dont le sujet est : « Faut-il interdire le téléphone portable au collège ? »</p><p>Pour chaque affirmation, choisissez la personne qui exprime cette idée.</p>', '<p><strong>Sophie</strong></p><p>Je suis professeure de mathématiques et, depuis que notre collège a interdit les téléphones, l''ambiance a changé : les élèves se parlent à la récréation et il y a moins de disputes nées sur les réseaux. Au début, ils protestaient ; aujourd''hui, beaucoup avouent qu''ils se sentent plus libres. Je ne vois vraiment pas pourquoi on reviendrait en arrière.</p><p><strong>Karim</strong></p><p>Mon fils prend deux bus pour aller au collège. Le téléphone, c''est ce qui me permet de savoir qu''il est bien arrivé, ou de le prévenir si je suis en retard. Qu''on l''interdise en classe, d''accord, c''est du bon sens. Mais le confisquer toute la journée, c''est ignorer la réalité des familles qui habitent loin.</p><p><strong>Hugo</strong></p><p>On parle toujours des dangers du téléphone, jamais de ce qu''il apporte. Moi, je l''utilise pour réviser avec des applications et pour traduire des mots en anglais. Le vrai problème, c''est que personne ne nous apprend à bien l''utiliser. Interdire, c''est facile ; éduquer, c''est plus long mais plus utile.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• confisquer (verbe) : tịch thu\n• la récréation : giờ ra chơi\n• du bon sens : điều hợp lý\n• revenir en arrière : quay lại như cũ\n• éduquer (verbe) : giáo dục","explications":"• Bài 3 của đề B2: ba ý kiến, mỗi nhận định chọn MỘT người. Một người có thể đúng cho nhiều câu.\n• Đọc lướt ba ý kiến, ghi bên cạnh mỗi tên 2, 3 ý chính (Sophie: ổn hơn, học sinh quen; Karim: liên lạc, chỉ cấm trong lớp; Hugo: lợi ích, dạy cách dùng).","kyNang":"B2-CE-3","vong":"hoc","thuTu":1}'::jsonb, '2026-11-14T20:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8pz034', 'b2ce188qd07b', 1, 'qcm', 'L''interdiction a amélioré les relations entre élèves.', '{"options":["Sophie","Karim","Hugo"]}'::jsonb, '{"answer":0}'::jsonb, 'Sophie : « les élèves se parlent à la récréation et il y a moins de disputes ».'), ('qmwgmy8pz035', 'b2ce188qd07b', 2, 'qcm', 'Il faudrait apprendre aux élèves à se servir de leur téléphone.', '{"options":["Sophie","Karim","Hugo"]}'::jsonb, '{"answer":2}'::jsonb, 'Hugo : « personne ne nous apprend à bien l''utiliser ».'), ('qmwgmy8pz036', 'b2ce188qd07b', 3, 'qcm', 'Le téléphone rassure les parents.', '{"options":["Sophie","Karim","Hugo"]}'::jsonb, '{"answer":1}'::jsonb, 'Karim : « me permet de savoir qu''il est bien arrivé ».'), ('qmwgmy8pz037', 'b2ce188qd07b', 4, 'qcm', 'Une interdiction limitée aux cours serait acceptable.', '{"options":["Sophie","Karim","Hugo"]}'::jsonb, '{"answer":1}'::jsonb, 'Karim : « Qu''on l''interdise en classe, d''accord ».'), ('qmwgmy8pz038', 'b2ce188qd07b', 5, 'qcm', 'Les élèves ont fini par apprécier la mesure.', '{"options":["Sophie","Karim","Hugo"]}'::jsonb, '{"answer":0}'::jsonb, 'Sophie : « Au début, ils protestaient ; aujourd''hui, beaucoup avouent qu''ils se sentent plus libres ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce198qd07c', 'practice', 'Lecture B2 : végétarien ou pas', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez l''opinion de ces trois personnes sur un forum francophone dont le sujet est : « Faut-il manger moins de viande ? »</p><p>Pour chaque affirmation, choisissez la personne qui exprime cette idée.</p>', '<p><strong>Élodie</strong></p><p>Je suis végétarienne depuis dix ans, mais je n''ai jamais essayé de convaincre ma famille. Chacun mange ce qu''il veut. En revanche, je trouve normal qu''on informe mieux sur l''impact de l''élevage intensif : la plupart des gens ne savent pas combien d''eau il faut pour produire un kilo de bœuf. Informer, ce n''est pas obliger.</p><p><strong>Marc</strong></p><p>Je suis éleveur dans le Cantal, et j''en ai assez qu''on fasse de nous les coupables. Mes vaches mangent de l''herbe, entretiennent les prairies et font vivre tout un village. Mettre dans le même sac un élevage comme le mien et une usine à poulets, c''est malhonnête. Mangez moins de viande si vous voulez, mais choisissez-la mieux.</p><p><strong>Inès</strong></p><p>Moi, je suis devenue flexitarienne pour une raison très simple : mon budget. La viande de qualité coûte cher, alors j''en mange deux fois par semaine, et je cuisine des lentilles et des pois chiches le reste du temps. Je n''en fais pas une question morale. Et franchement, je n''ai jamais aussi bien mangé.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''élevage intensif : chăn nuôi công nghiệp\n• une prairie : đồng cỏ\n• mettre dans le même sac : vơ đũa cả nắm\n• flexitarien (adjectif) : ăn chay linh hoạt\n• les pois chiches : đậu gà","explications":"• Nhận định trong câu hỏi được DIỄN ĐẠT LẠI, không chép nguyên chữ: « confondre » = « mettre dans le même sac ».\n• Hai người cùng nói « manger moins » nhưng lý do khác: tìm lý do để phân biệt (tiền, môi trường, chất lượng).","kyNang":"B2-CE-3","vong":"hoc","thuTu":2}'::jsonb, '2026-11-14T20:00:18.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8pz039', 'b2ce198qd07c', 1, 'qcm', 'Il ne faut pas confondre les différents types d''élevage.', '{"options":["Élodie","Marc","Inès"]}'::jsonb, '{"answer":1}'::jsonb, 'Marc : « Mettre dans le même sac un élevage comme le mien et une usine à poulets, c''est malhonnête ».'), ('qmwgmy8pz03a', 'b2ce198qd07c', 2, 'qcm', 'Son choix alimentaire est d''abord une question d''argent.', '{"options":["Élodie","Marc","Inès"]}'::jsonb, '{"answer":2}'::jsonb, 'Inès : « pour une raison très simple : mon budget ».'), ('qmwgmy8pz03b', 'b2ce198qd07c', 3, 'qcm', 'Le public manque d''informations sur la production de viande.', '{"options":["Élodie","Marc","Inès"]}'::jsonb, '{"answer":0}'::jsonb, 'Élodie : « la plupart des gens ne savent pas combien d''eau il faut ».'), ('qmwgmy8pz03c', 'b2ce198qd07c', 4, 'qcm', 'Son alimentation s''est améliorée en changeant ses habitudes.', '{"options":["Élodie","Marc","Inès"]}'::jsonb, '{"answer":2}'::jsonb, 'Inès : « je n''ai jamais aussi bien mangé ».'), ('qmwgmy8pz03d', 'b2ce198qd07c', 5, 'qcm', 'Elle respecte les choix alimentaires de ses proches.', '{"options":["Élodie","Marc","Inès"]}'::jsonb, '{"answer":0}'::jsonb, 'Élodie : « je n''ai jamais essayé de convaincre ma famille. Chacun mange ce qu''il veut ».'), ('qmwgmy8pz03e', 'b2ce198qd07c', 6, 'qcm', 'Il conseille de privilégier la qualité plutôt que la quantité.', '{"options":["Élodie","Marc","Inès"]}'::jsonb, '{"answer":1}'::jsonb, 'Marc : « Mangez moins de viande si vous voulez, mais choisissez-la mieux ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce208qe07d', 'practice', 'Lecture B2 : la retraite à 60 ans', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez l''opinion de ces trois personnes sur un forum francophone dont le sujet est : « Faut-il revenir à la retraite à 60 ans ? »</p><p>Pour chaque affirmation, choisissez la personne qui exprime cette idée.</p>', '<p><strong>Gérard</strong></p><p>J''ai commencé à travailler sur des chantiers à dix-sept ans. À cinquante-huit ans, mon dos ne suit plus, et je ne suis pas le seul. Pour nous, partir à soixante ans n''est pas un caprice, c''est une question de santé. Qu''un cadre qui travaille assis parte plus tard, je le comprends, mais on ne peut pas appliquer la même règle à tout le monde.</p><p><strong>Nathalie</strong></p><p>Je suis infirmière et j''adore mon métier, mais je vois bien que notre population vieillit. Il y a de moins en moins d''actifs pour financer les pensions. Je ne suis pas ravie de travailler plus longtemps, mais je préfère ça plutôt que de voir les retraites baisser pour mes enfants. Il faut être réaliste.</p><p><strong>Thomas</strong></p><p>J''ai trente ans et, franchement, je ne crois plus que je toucherai une retraite correcte. Alors j''épargne de mon côté. Ce qui me choque, c''est que le débat ne porte que sur l''âge. Personne ne parle des seniors qu''on pousse vers la sortie bien avant soixante ans : à quoi sert de reculer l''âge si les entreprises n''embauchent pas les plus de cinquante-cinq ans ?</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un chantier : công trường\n• un caprice : ý thích nhất thời\n• un actif : người đang đi làm\n• épargner (verbe) : tiết kiệm\n• la pénibilité : sự nặng nhọc","explications":"• Nhận định thường dùng từ trừu tượng (« pénibilité », « démographique ») cho ý mà người viết nói bằng ví dụ cụ thể (« mon dos ne suit plus », « population vieillit »).\n• Một nhận định có thể khớp mơ hồ với hai người: chọn người nói RÕ nhất, có câu làm bằng chứng.","kyNang":"B2-CE-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-14T20:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8pz03f', 'b2ce208qe07d', 1, 'qcm', 'L''âge de départ devrait dépendre de la pénibilité du métier.', '{"options":["Gérard","Nathalie","Thomas"]}'::jsonb, '{"answer":0}'::jsonb, 'Gérard : « on ne peut pas appliquer la même règle à tout le monde ».'), ('qmwgmy8pz03g', 'b2ce208qe07d', 2, 'qcm', 'Il doute de pouvoir compter un jour sur une pension suffisante.', '{"options":["Gérard","Nathalie","Thomas"]}'::jsonb, '{"answer":2}'::jsonb, 'Thomas : « je ne crois plus que je toucherai une retraite correcte ».'), ('qmwgmy8pz03h', 'b2ce208qe07d', 3, 'qcm', 'Elle accepte un effort pour protéger les générations futures.', '{"options":["Gérard","Nathalie","Thomas"]}'::jsonb, '{"answer":1}'::jsonb, 'Nathalie : « plutôt que de voir les retraites baisser pour mes enfants ».'), ('qmwgmy8pz03i', 'b2ce208qe07d', 4, 'qcm', 'Le débat oublie la situation des salariés âgés au travail.', '{"options":["Gérard","Nathalie","Thomas"]}'::jsonb, '{"answer":2}'::jsonb, 'Thomas : « Personne ne parle des seniors qu''on pousse vers la sortie ».'), ('qmwgmy8pz03j', 'b2ce208qe07d', 5, 'qcm', 'L''évolution démographique rend un changement nécessaire.', '{"options":["Gérard","Nathalie","Thomas"]}'::jsonb, '{"answer":1}'::jsonb, 'Nathalie : « notre population vieillit. Il y a de moins en moins d''actifs ».'), ('qmwgmy8pz03k', 'b2ce208qe07d', 6, 'qcm', 'Sa demande ne relève pas du confort personnel.', '{"options":["Gérard","Nathalie","Thomas"]}'::jsonb, '{"answer":0}'::jsonb, 'Gérard : « partir à soixante ans n''est pas un caprice, c''est une question de santé ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce218qe07e', 'practice', 'Lecture B2 : les cours de langue en ligne', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez l''opinion de ces trois personnes sur un forum francophone dont le sujet est : « Peut-on vraiment apprendre une langue en ligne ? »</p><p>Pour chaque affirmation, choisissez la personne qui exprime cette idée.</p>', '<p><strong>Lina</strong></p><p>J''apprends l''italien avec une application depuis deux ans, dix minutes par jour, dans le métro. C''est pratique et ça m''a donné de bonnes bases de vocabulaire. Mais le jour où je suis arrivée à Rome, j''étais incapable de suivre une conversation. Les applications donnent l''illusion de progresser ; il manque l''essentiel : parler avec de vraies personnes.</p><p><strong>Pascal</strong></p><p>Je donne des cours d''anglais par visioconférence depuis cinq ans. Mes élèves vivent dans des villages, travaillent en horaires décalés ou s''occupent de jeunes enfants : ils ne pourraient jamais venir dans une école. Pour eux, le cours en ligne n''est pas un choix par défaut, c''est la seule possibilité. Et avec une bonne connexion, on travaille aussi bien qu''en salle.</p><p><strong>Mei</strong></p><p>J''ai essayé les deux. En ligne, j''avais tendance à faire autre chose en même temps : regarder mes messages, préparer un café. En classe, avec d''autres apprenants, je suis plus concentrée et je n''ose pas venir sans avoir fait mes devoirs. Je crois que ça dépend surtout de la personnalité : certains ont besoin d''un cadre.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la visioconférence : họp, học qua video\n• des horaires décalés : giờ làm lệch ca\n• par défaut : vì không còn cách khác\n• un apprenant : người học\n• un cadre : khuôn khổ, nề nếp","explications":"• Chú ý phân biệt « en ligne » theo hai nghĩa: ứng dụng tự học (Lina) và lớp có giáo viên qua video (Pascal).\n• Nhận định về bản thân (« Elle a découvert… », « l''aide à… ») ứng với người kể trải nghiệm riêng.","isPremium":true,"price":19000,"kyNang":"B2-CE-3","vong":"hoc","thuTu":4}'::jsonb, '2026-11-14T20:00:20.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8pz03l', 'b2ce218qe07e', 1, 'qcm', 'L''enseignement à distance ouvre l''apprentissage à des personnes isolées.', '{"options":["Lina","Pascal","Mei"]}'::jsonb, '{"answer":1}'::jsonb, 'Pascal : « ils ne pourraient jamais venir dans une école ».'), ('qmwgmy8pz03m', 'b2ce218qe07e', 2, 'qcm', 'Les applications ne suffisent pas pour communiquer réellement.', '{"options":["Lina","Pascal","Mei"]}'::jsonb, '{"answer":0}'::jsonb, 'Lina : « il manque l''essentiel : parler avec de vraies personnes ».'), ('qmwgmy8pz03n', 'b2ce218qe07e', 3, 'qcm', 'La présence des autres l''aide à rester sérieuse.', '{"options":["Lina","Pascal","Mei"]}'::jsonb, '{"answer":2}'::jsonb, 'Mei : « avec d''autres apprenants, je suis plus concentrée et je n''ose pas venir sans avoir fait mes devoirs ».'), ('qmwgmy8pz03o', 'b2ce218qe07e', 4, 'qcm', 'L''efficacité dépend du caractère de chacun.', '{"options":["Lina","Pascal","Mei"]}'::jsonb, '{"answer":2}'::jsonb, 'Mei : « ça dépend surtout de la personnalité ».'), ('qmwgmy8pz03p', 'b2ce218qe07e', 5, 'qcm', 'Un cours en ligne peut être aussi efficace qu''un cours en salle.', '{"options":["Lina","Pascal","Mei"]}'::jsonb, '{"answer":1}'::jsonb, 'Pascal : « on travaille aussi bien qu''en salle ».'), ('qmwgmy8pz03q', 'b2ce218qe07e', 6, 'qcm', 'Elle a découvert ses limites lors d''un voyage.', '{"options":["Lina","Pascal","Mei"]}'::jsonb, '{"answer":0}'::jsonb, 'Lina : « le jour où je suis arrivée à Rome, j''étais incapable de suivre une conversation ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce228qe07f', 'practice', 'Lecture B2 : le vote obligatoire', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez l''opinion de ces trois personnes sur un forum francophone dont le sujet est : « Faut-il rendre le vote obligatoire ? »</p><p>Pour chaque affirmation, choisissez la personne qui exprime cette idée.</p>', '<p><strong>Arnaud</strong></p><p>Je suis favorable au vote obligatoire, comme en Belgique. Quand seulement la moitié des électeurs se déplacent, les élus ne représentent qu''une partie du pays. Une petite amende suffirait à rappeler que voter est un devoir autant qu''un droit. Mais à une condition : que le vote blanc soit enfin reconnu, pour qu''on puisse dire qu''aucun candidat ne nous convient.</p><p><strong>Céline</strong></p><p>Rendre le vote obligatoire, c''est soigner le symptôme et non la maladie. Si les gens ne votent plus, c''est qu''ils ont le sentiment que leur voix ne change rien. Moi, je préférerais qu''on les consulte plus souvent, sur des questions concrètes de leur ville ou de leur quartier. On retrouverait le goût de voter sans avoir besoin de sanction.</p><p><strong>Yasmine</strong></p><p>Je comprends l''idée, et je vote moi-même à chaque élection. Mais obliger quelqu''un qui ne s''intéresse pas du tout à la politique, c''est l''inviter à choisir au hasard, ou pour le candidat qui crie le plus fort. Je pense qu''il faut commencer par l''école : des cours où l''on explique vraiment comment fonctionnent les institutions.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un électeur : cử tri\n• une amende : tiền phạt\n• le vote blanc : phiếu trắng\n• l''abstention (nom féminin) : việc không đi bầu\n• une sanction : hình phạt","explications":"• Ý kiến gần giống nhau: Céline và Yasmine đều không ủng hộ bắt buộc, nhưng giải pháp khác (hỏi ý dân địa phương / dạy ở trường). Phân biệt bằng GIẢI PHÁP.\n• Céline nói « sans avoir besoin de sanction », Arnaud muốn « une petite amende »: chú ý chữ phủ định.","isPremium":true,"price":19000,"kyNang":"B2-CE-3","vong":"on","thuTu":5}'::jsonb, '2026-11-14T20:00:21.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8pz03r', 'b2ce228qe07f', 1, 'qcm', 'Une obligation pourrait produire des votes peu réfléchis.', '{"options":["Arnaud","Céline","Yasmine"]}'::jsonb, '{"answer":2}'::jsonb, 'Yasmine : « c''est l''inviter à choisir au hasard ».'), ('qmwgmy8pz03s', 'b2ce228qe07f', 2, 'qcm', 'L''abstention vient d''un sentiment d''impuissance.', '{"options":["Arnaud","Céline","Yasmine"]}'::jsonb, '{"answer":1}'::jsonb, 'Céline : « ils ont le sentiment que leur voix ne change rien ».'), ('qmwgmy8pz03t', 'b2ce228qe07f', 3, 'qcm', 'Il pose une condition à l''obligation de voter.', '{"options":["Arnaud","Céline","Yasmine"]}'::jsonb, '{"answer":0}'::jsonb, 'Arnaud : « Mais à une condition : que le vote blanc soit enfin reconnu ».'), ('qmwgmy8pz03u', 'b2ce228qe07f', 4, 'qcm', 'La solution passe par l''éducation des jeunes.', '{"options":["Arnaud","Céline","Yasmine"]}'::jsonb, '{"answer":2}'::jsonb, 'Yasmine : « il faut commencer par l''école ».'), ('qmwgmy8pz03v', 'b2ce228qe07f', 5, 'qcm', 'Une sanction financière serait utile.', '{"options":["Arnaud","Céline","Yasmine"]}'::jsonb, '{"answer":0}'::jsonb, 'Arnaud : « Une petite amende suffirait ».'), ('qmwgmy8pz03w', 'b2ce228qe07f', 6, 'qcm', 'Les citoyens devraient participer à des décisions locales.', '{"options":["Arnaud","Céline","Yasmine"]}'::jsonb, '{"answer":1}'::jsonb, 'Céline : « sur des questions concrètes de leur ville ou de leur quartier ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce238qe07g', 'practice', 'Lecture B2 : le forum de discussion', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez l''opinion de ces trois personnes sur un forum francophone dont le sujet est : « Faut-il interdire la publicité pour les produits trop sucrés ? »</p><p>Pour chaque affirmation, choisissez la personne qui exprime cette idée.</p>', '<p><strong>Laurent</strong></p><p>Je suis pédiatre et je vois chaque semaine des enfants en surpoids dès huit ans. Les publicités pour les céréales ou les sodas visent directement les enfants, avec des personnages de dessins animés et des cadeaux dans les paquets. Un enfant de six ans ne sait pas faire la différence entre un message publicitaire et un conseil. Il faut interdire ces publicités aux heures où les enfants sont devant les écrans.</p><p><strong>Amélie</strong></p><p>Interdire la publicité ne changera pas grand-chose si, à la maison, les placards sont remplis de biscuits. Les parents ont leur part de responsabilité. Je préférerais que l''argent public serve à des ateliers de cuisine dans les écoles et à rendre les fruits et légumes moins chers. On mange souvent mal parce que bien manger coûte trop cher.</p><p><strong>Rachid</strong></p><p>Je travaille dans une agence de communication, donc je connais la force d''une publicité. Mais une interdiction totale frapperait aussi de petites entreprises locales, des confiseurs artisanaux par exemple. Je serais plutôt favorable à des règles strictes : une information claire sur le taux de sucre, visible dans chaque publicité, et aucune promotion avec des jouets.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un pédiatre : bác sĩ nhi\n• le surpoids : thừa cân\n• un confiseur : thợ làm kẹo\n• le taux de sucre : hàm lượng đường\n• encadrer (verbe) : đặt khuôn khổ, quy định","explications":"• Đúng định dạng đề: 6 nhận định, 3 người, khoảng 15 phút. Đọc 6 nhận định TRƯỚC, rồi đọc từng ý kiến và đánh dấu nhận định nào khớp.\n• Rachid và Laurent cùng nói về quảng cáo cho trẻ: Laurent muốn CẤM theo giờ, Rachid muốn QUY ĐỊNH chặt. Phân biệt mức độ.","isPremium":true,"price":19000,"kyNang":"B2-CE-3","vong":"chot","thuTu":6}'::jsonb, '2026-11-14T20:00:22.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8pz03x', 'b2ce238qe07g', 1, 'qcm', 'Les jeunes enfants ne savent pas reconnaître une publicité.', '{"options":["Laurent","Amélie","Rachid"]}'::jsonb, '{"answer":0}'::jsonb, 'Laurent : « Un enfant de six ans ne sait pas faire la différence entre un message publicitaire et un conseil ».'), ('qmwgmy8pz03y', 'b2ce238qe07g', 2, 'qcm', 'Le prix des aliments sains explique en partie la mauvaise alimentation.', '{"options":["Laurent","Amélie","Rachid"]}'::jsonb, '{"answer":1}'::jsonb, 'Amélie : « On mange souvent mal parce que bien manger coûte trop cher ».'), ('qmwgmy8pz03z', 'b2ce238qe07g', 3, 'qcm', 'Une interdiction aurait des conséquences pour de petits producteurs.', '{"options":["Laurent","Amélie","Rachid"]}'::jsonb, '{"answer":2}'::jsonb, 'Rachid : « frapperait aussi de petites entreprises locales ».'), ('qmwgmy8pz040', 'b2ce238qe07g', 4, 'qcm', 'Les familles sont aussi responsables de ce que mangent les enfants.', '{"options":["Laurent","Amélie","Rachid"]}'::jsonb, '{"answer":1}'::jsonb, 'Amélie : « Les parents ont leur part de responsabilité ».'), ('qmwgmy8pz041', 'b2ce238qe07g', 5, 'qcm', 'Il faudrait encadrer les publicités plutôt que les supprimer.', '{"options":["Laurent","Amélie","Rachid"]}'::jsonb, '{"answer":2}'::jsonb, 'Rachid : « Je serais plutôt favorable à des règles strictes ».'), ('qmwgmy8pz042', 'b2ce238qe07g', 6, 'qcm', 'Il s''appuie sur ce qu''il observe dans son travail.', '{"options":["Laurent","Amélie","Rachid"]}'::jsonb, '{"answer":0}'::jsonb, 'Laurent : « je vois chaque semaine des enfants en surpoids dès huit ans ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce248qe07h', 'practice', 'Lecture B2 : sans doute ou sans aucun doute ?', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte. Faites attention aux mots qui indiquent le degré de certitude, la condition ou la concession, puis répondez aux questions.</p>', '<p><strong>Une découverte sous le parking</strong></p><p>Lors de travaux sous un parking du centre de Lyon, des ouvriers ont mis au jour des murs anciens. Il s''agit sans aucun doute de vestiges romains : les archéologues ont retrouvé des pièces de monnaie portant le nom d''un empereur. Le bâtiment était sans doute une maison de riches commerçants, car on y a trouvé des fragments de mosaïque.</p><p>Il est possible qu''il ait été détruit par un incendie, mais les traces de cendres sont encore à analyser. Selon le responsable du chantier, le site pourrait s''étendre sous les immeubles voisins, ce qui reste à vérifier.</p><p>Une chose est certaine : les travaux du parking sont suspendus pour au moins six mois. Quant à l''ouverture du site au public, elle semble peu probable, faute de place. Les habitants, eux, sont visiblement ravis : beaucoup sont venus photographier les fouilles derrière les barrières.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• mettre au jour : làm lộ ra, khai quật\n• des vestiges (nom masculin) : di tích\n• sans aucun doute : chắc chắn\n• sans doute : có lẽ\n• visiblement (adverbe) : rõ ràng là (nhìn thấy được)","explications":"• Thang chắc chắn: « certain, sans aucun doute » > « sans doute, probablement » > « il est possible que, pourrait » > « peu probable ».\n• « sans doute » ngày nay nghĩa là CÓ LẼ, không phải « chắc chắn »: đây là bẫy kinh điển.","kyNang":"B2-CE-4","vong":"hoc","thuTu":1}'::jsonb, '2026-11-14T20:00:23.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8q0043', 'b2ce248qe07h', 1, 'qcm', 'Que sait-on de l''origine des murs ?', '{"options":["C''est certain : ils sont romains.","C''est une simple hypothèse du chantier.","C''est probable, mais pas encore sûr."]}'::jsonb, '{"answer":0}'::jsonb, '« sans aucun doute » = chắc chắn, có bằng chứng là « des pièces de monnaie portant le nom d''un empereur ».'), ('qmwgmy8q0044', 'b2ce248qe07h', 2, 'qcm', 'Le bâtiment était une maison de commerçants. Selon le texte, c''est…', '{"options":["probable.","certain.","exclu."]}'::jsonb, '{"answer":0}'::jsonb, 'Bẫy hay gặp: « sans doute » (không có « aucun ») chỉ là CÓ LẼ: « était sans doute une maison de riches commerçants ».'), ('qmwgmy8q0045', 'b2ce248qe07h', 3, 'qcm', 'L''incendie est présenté comme…', '{"options":["un fait établi par les archéologues.","une possibilité non confirmée.","une idée rejetée par les experts."]}'::jsonb, '{"answer":1}'::jsonb, '« Il est possible qu''il ait été détruit par un incendie ».'), ('qmwgmy8q0046', 'b2ce248qe07h', 4, 'qcm', 'Pourquoi l''hypothèse de l''incendie n''est-elle pas confirmée ?', '{"options":["Les cendres n''ont pas encore été analysées.","Les archéologues n''ont trouvé aucune cendre.","Les ouvriers ont détruit les traces de feu."]}'::jsonb, '{"answer":0}'::jsonb, '« les traces de cendres sont encore à analyser ».'), ('qmwgmy8q0047', 'b2ce248qe07h', 5, 'qcm', 'L''extension du site sous les immeubles voisins est…', '{"options":["une information déjà démentie.","une hypothèse à vérifier.","une certitude du responsable."]}'::jsonb, '{"answer":1}'::jsonb, '« pourrait s''étendre… ce qui reste à vérifier ».'), ('qmwgmy8q0048', 'b2ce248qe07h', 6, 'qcm', 'Quelle information est présentée comme sûre ?', '{"options":["L''ouverture prochaine du site au public.","La destruction de la maison par le feu.","La suspension des travaux du parking."]}'::jsonb, '{"answer":2}'::jsonb, '« Une chose est certaine : les travaux du parking sont suspendus ».'), ('qmwgmy8q0049', 'b2ce248qe07h', 7, 'qcm', 'L''ouverture du site au public est…', '{"options":["très probable.","peu probable.","déjà décidée."]}'::jsonb, '{"answer":1}'::jsonb, '« elle semble peu probable, faute de place ».'), ('qmwgmy8q004a', 'b2ce248qe07h', 8, 'qcm', 'Le mot visiblement indique que le journaliste…', '{"options":["déduit la joie des habitants de ce qu''il voit.","a interrogé un par un les habitants venus voir les fouilles.","doute de la joie réelle des habitants."]}'::jsonb, '{"answer":0}'::jsonb, '« visiblement ravis : beaucoup sont venus photographier les fouilles »: nhà báo suy ra từ điều quan sát được.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce258qe07i', 'practice', 'Lecture B2 : il se pourrait que', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte. Faites attention aux mots qui indiquent le degré de certitude, la condition ou la concession, puis répondez aux questions.</p>', '<p><strong>Une nouvelle ligne de tramway ?</strong></p><p>La métropole étudie la création d''une nouvelle ligne de tramway entre la gare et le campus. Si le projet est validé en décembre, les travaux commenceraient au printemps 2028. Il se pourrait toutefois que ce calendrier glisse : l''État n''a pas encore confirmé sa participation financière.</p><p>La métropole ne lancera les travaux qu''à condition d''obtenir au moins un tiers du budget de l''État. Au cas où cette aide serait refusée, une ligne de bus rapide serait construite à la place, pour un coût deux fois moins élevé.</p><p>Les commerçants de l''avenue principale, eux, ne s''opposeront pas au tramway, à moins que les travaux ne durent plus d''un an devant leurs boutiques. Quant aux étudiants, ils auraient pu avoir leur tramway dès 2020 si le premier projet n''avait pas été abandonné faute d''argent.</p><p>La présidente de la métropole se dit confiante : « Pour peu que chacun joue le jeu, la ligne sera ouverte avant la fin de la décennie. »</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• glisser (verbe) : (lịch) bị trễ, trượt\n• à condition de / que : với điều kiện\n• au cas où : trong trường hợp\n• à moins que : trừ khi\n• pour peu que : chỉ cần, miễn là","explications":"• Chú ý thì động từ: « commenceraient » (điều kiện, chưa chắc) khác « commenceront » (chắc chắn sẽ).\n• « auraient pu… si… n''avait pas » nói về quá khứ đã không xảy ra: thường mang ý tiếc nuối.","isPremium":true,"price":19000,"kyNang":"B2-CE-4","vong":"hoc","thuTu":2}'::jsonb, '2026-11-14T20:00:24.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8q004b', 'b2ce258qe07i', 1, 'qcm', 'Les travaux commenceront-ils au printemps 2028 ?', '{"options":["Oui, la date est déjà fixée par l''État et par la métropole.","Non, le projet vient d''être abandonné.","Seulement si le projet est validé en décembre."]}'::jsonb, '{"answer":2}'::jsonb, '« Si le projet est validé en décembre, les travaux commenceraient ».'), ('qmwgmy8q004c', 'b2ce258qe07i', 2, 'qcm', 'La phrase sur le calendrier qui glisse signifie qu''…', '{"options":["un retard est certain.","les travaux seront avancés.","un retard est possible."]}'::jsonb, '{"answer":2}'::jsonb, '« Il se pourrait toutefois que ce calendrier glisse »: có thể trễ, chưa chắc.'), ('qmwgmy8q004d', 'b2ce258qe07i', 3, 'qcm', 'Quelle condition la métropole pose-t-elle ?', '{"options":["Que l''État paie au moins un tiers du projet.","Que les étudiants votent pour le tramway.","Que les commerçants acceptent les travaux."]}'::jsonb, '{"answer":0}'::jsonb, '« à condition d''obtenir au moins un tiers du budget de l''État ».'), ('qmwgmy8q004e', 'b2ce258qe07i', 4, 'qcm', 'Que se passera-t-il si l''État refuse son aide ?', '{"options":["Le projet sera reporté à 2040.","Un bus rapide remplacera le tramway.","La métropole paiera seule le tramway."]}'::jsonb, '{"answer":1}'::jsonb, '« Au cas où cette aide serait refusée, une ligne de bus rapide serait construite à la place ».'), ('qmwgmy8q004f', 'b2ce258qe07i', 5, 'qcm', 'Dans quel cas les commerçants s''opposeraient-ils au tramway ?', '{"options":["Si les travaux duraient plus d''un an devant chez eux.","Si la ligne ne passait pas devant leurs boutiques.","Si le prix du ticket était trop élevé."]}'::jsonb, '{"answer":0}'::jsonb, '« à moins que les travaux ne durent plus d''un an devant leurs boutiques »: « à moins que » = trừ khi.'), ('qmwgmy8q004g', 'b2ce258qe07i', 6, 'qcm', 'Qu''apprend-on sur le premier projet ?', '{"options":["Il a été abandonné pour des raisons financières.","Il a été refusé par les étudiants et les professeurs du campus.","Il est toujours en cours de réalisation."]}'::jsonb, '{"answer":0}'::jsonb, '« si le premier projet n''avait pas été abandonné faute d''argent ».'), ('qmwgmy8q004h', 'b2ce258qe07i', 7, 'qcm', 'La phrase sur les étudiants exprime…', '{"options":["ce qui aurait pu se passer dans le passé.","une condition pour l''avenir.","une promesse faite aux étudiants pour l''année prochaine."]}'::jsonb, '{"answer":0}'::jsonb, 'Điều kiện loại 3 (quá khứ không xảy ra): « ils auraient pu avoir leur tramway dès 2020 ».'), ('qmwgmy8q004i', 'b2ce258qe07i', 8, 'qcm', 'Que veut dire la présidente avec la formule pour peu que chacun joue le jeu ?', '{"options":["Bien que personne ne coopère.","Parce que tout le monde a coopéré.","À condition que tous coopèrent."]}'::jsonb, '{"answer":2}'::jsonb, '« Pour peu que » = chỉ cần, với điều kiện là: « Pour peu que chacun joue le jeu ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce268qf07j', 'practice', 'Lecture B2 : bien que, même si', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte. Faites attention aux mots qui indiquent le degré de certitude, la condition ou la concession, puis répondez aux questions.</p>', '<p><strong>Le nouveau musée de la mer</strong></p><p>Bien que le bâtiment soit superbe, le nouveau musée de la mer laisse une impression mitigée. Les salles consacrées aux poissons des grands fonds sont spectaculaires, même si les explications restent souvent trop techniques pour les enfants. Certes, le prix d''entrée est élevé, mais il comprend l''accès à l''aquarium géant, ce qui le rend raisonnable pour une famille.</p><p>En revanche, la salle sur la pollution des océans, pourtant annoncée comme le cœur du musée, se limite à quelques panneaux. Malgré les efforts du personnel, très accueillant, les files d''attente dépassent souvent une heure le week-end. Quoi qu''en dise la direction, le restaurant du dernier étage n''est pas à la hauteur de la vue.</p><p>Le musée vaut néanmoins la visite, ne serait-ce que pour ses méduses, qu''on pourrait regarder pendant des heures. Encore faut-il venir en semaine.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• mitigé (adjectif) : lẫn lộn, nửa khen nửa chê\n• certes… mais : đúng là… nhưng\n• malgré (préposition) : mặc dù\n• quoi qu''en dise : dù… có nói gì\n• encore faut-il : nhưng còn phải","explications":"• Câu nhượng bộ có hai vế: vế sau « bien que, même si, malgré » là điều tác giả THỪA NHẬN, vế còn lại mới là ý chính.\n• « Certes… mais », « pourtant », « néanmoins », « encore faut-il » đều báo đổi chiều.","isPremium":true,"price":19000,"kyNang":"B2-CE-4","vong":"hoc","thuTu":3}'::jsonb, '2026-11-14T20:00:25.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8q004j', 'b2ce268qf07j', 1, 'qcm', 'Quelle est l''impression générale de l''auteur ?', '{"options":["Très enthousiaste.","Entièrement négative.","Partagée."]}'::jsonb, '{"answer":2}'::jsonb, '« laisse une impression mitigée »: vừa khen vừa chê.'), ('qmwgmy8q004k', 'b2ce268qf07j', 2, 'qcm', 'Que reconnaît l''auteur dans la première phrase, malgré sa réserve ?', '{"options":["La rapidité de l''accueil.","La qualité du restaurant.","La beauté du bâtiment."]}'::jsonb, '{"answer":2}'::jsonb, '« Bien que le bâtiment soit superbe ».'), ('qmwgmy8q004l', 'b2ce268qf07j', 3, 'qcm', 'Les explications des salles des grands fonds…', '{"options":["sont parfaites pour toute la famille.","sont difficiles pour un jeune public.","sont absentes de certaines salles."]}'::jsonb, '{"answer":1}'::jsonb, '« même si les explications restent souvent trop techniques pour les enfants ».'), ('qmwgmy8q004m', 'b2ce268qf07j', 4, 'qcm', 'Que pense l''auteur du prix d''entrée ?', '{"options":["Il est trop cher pour une famille.","Il est élevé mais justifié.","Il est bas pour un tel musée."]}'::jsonb, '{"answer":1}'::jsonb, '« Certes, le prix d''entrée est élevé, mais… ce qui le rend raisonnable pour une famille ».'), ('qmwgmy8q004n', 'b2ce268qf07j', 5, 'qcm', 'Que reproche-t-il à la salle sur la pollution ?', '{"options":["Elle est beaucoup trop grande, trop sombre et mal indiquée dans le musée.","Elle déçoit alors qu''elle devait être centrale.","Elle est fermée le week-end."]}'::jsonb, '{"answer":1}'::jsonb, '« pourtant annoncée comme le cœur du musée, se limite à quelques panneaux ».'), ('qmwgmy8q004o', 'b2ce268qf07j', 6, 'qcm', 'Selon l''auteur, le personnel…', '{"options":["est trop peu nombreux le week-end.","est accueillant mais ne peut pas éviter l''attente.","est désagréable avec les visiteurs pressés du week-end."]}'::jsonb, '{"answer":1}'::jsonb, '« Malgré les efforts du personnel, très accueillant, les files d''attente dépassent souvent une heure ».'), ('qmwgmy8q004p', 'b2ce268qf07j', 7, 'qcm', 'La formule quoi qu''en dise la direction montre que l''auteur…', '{"options":["répète fidèlement l''opinion de la direction du musée.","ne partage pas l''avis de la direction.","n''a pas parlé avec la direction."]}'::jsonb, '{"answer":1}'::jsonb, '« Quoi qu''en dise la direction » = dù ban giám đốc nói gì đi nữa: tác giả không đồng ý.'), ('qmwgmy8q004q', 'b2ce268qf07j', 8, 'qcm', 'Que conseille finalement l''auteur ?', '{"options":["Visiter le musée, plutôt en semaine.","Éviter ce musée, trop cher pour ce qu''il propose.","Venir surtout le week-end."]}'::jsonb, '{"answer":0}'::jsonb, '« Le musée vaut néanmoins la visite… Encore faut-il venir en semaine ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce278qf07k', 'practice', 'Lecture B2 : nuances d''un article', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Vous lisez cet article dans un journal francophone. Répondez aux questions en choisissant la bonne réponse.</p>', '<p><strong>Le café, bon pour le cœur ?</strong></p><p>Une étude publiée cette semaine suggère que boire deux à trois tasses de café par jour pourrait réduire le risque de maladies cardiaques. Les chercheurs ont suivi près de quatre cent mille adultes pendant douze ans. Ceux qui buvaient du café modérément auraient eu un risque inférieur de dix à quinze pour cent à celui des non-buveurs.</p><p>Faut-il pour autant se précipiter vers la machine à café ? Pas si vite, préviennent plusieurs spécialistes. L''étude montre une association, pas une cause : les buveurs de café ont peut-être d''autres habitudes, comme une vie plus active, qui expliqueraient ces résultats. Les auteurs eux-mêmes le reconnaissent, tout en jugeant cette explication insuffisante.</p><p>Par ailleurs, les effets semblent varier selon les personnes. Chez certains, le café provoque des palpitations ou des troubles du sommeil, ce qui annule largement ses bénéfices supposés. Quant aux femmes enceintes, la prudence reste de mise.</p><p>Une seule conclusion fait l''unanimité : pour la plupart des adultes en bonne santé, une consommation modérée n''est pas dangereuse. Ce qui, après des décennies de soupçons, constitue déjà une petite révolution.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• suggérer (verbe) : gợi ý, cho thấy\n• une association : mối liên hệ (thống kê)\n• des palpitations (nom féminin) : tim đập nhanh\n• de mise : nên có, phù hợp\n• faire l''unanimité : được mọi người đồng ý","explications":"• Báo khoa học có nhiều tầng chắc chắn: « suggère », « pourrait », « auraient » (chưa chắc) khác « fait l''unanimité » (chắc).\n• « association, pas une cause »: tương quan không phải nhân quả, câu hỏi B2 hay hỏi ý này.","isPremium":true,"price":19000,"kyNang":"B2-CE-4","vong":"on","thuTu":4}'::jsonb, '2026-11-14T20:00:26.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8q004r', 'b2ce278qf07k', 1, 'qcm', 'Que dit l''étude, d''après le premier paragraphe ?', '{"options":["Le café pourrait réduire un risque, sans certitude.","Le café guérit à coup sûr les maladies cardiaques chez les adultes.","Le café augmente le risque cardiaque."]}'::jsonb, '{"answer":0}'::jsonb, '« suggère que boire deux à trois tasses de café par jour pourrait réduire le risque ».'), ('qmwgmy8q004s', 'b2ce278qf07k', 2, 'qcm', 'Pourquoi le journaliste emploie-t-il le conditionnel auraient eu ?', '{"options":["Pour annoncer un résultat futur.","Pour rapporter un résultat sans le garantir.","Pour exprimer un regret sur une occasion manquée."]}'::jsonb, '{"answer":1}'::jsonb, '« auraient eu un risque inférieur »: thức điều kiện báo chí, thuật lại thông tin chưa được xác nhận.'), ('qmwgmy8q004t', 'b2ce278qf07k', 3, 'qcm', 'Selon les spécialistes, quelle est la principale limite de l''étude ?', '{"options":["Elle montre un lien, pas une cause.","Elle a suivi trop peu de personnes.","Elle a duré trop peu de temps."]}'::jsonb, '{"answer":0}'::jsonb, '« L''étude montre une association, pas une cause ».'), ('qmwgmy8q004u', 'b2ce278qf07k', 4, 'qcm', 'Quelle est la position des auteurs de l''étude ?', '{"options":["Ils reconnaissent que leur étude est fausse.","Ils admettent la limite mais la jugent insuffisante.","Ils refusent toute critique de leur travail et défendent leurs conclusions."]}'::jsonb, '{"answer":1}'::jsonb, '« Les auteurs eux-mêmes le reconnaissent, tout en jugeant cette explication insuffisante ».'), ('qmwgmy8q004v', 'b2ce278qf07k', 5, 'qcm', 'Que signifie l''expression bénéfices supposés ?', '{"options":["Des avantages qui ne sont pas encore prouvés.","Des avantages connus et prouvés depuis longtemps.","Des avantages réservés aux femmes."]}'::jsonb, '{"answer":0}'::jsonb, '« ses bénéfices supposés »: lợi ích được giả định, chưa chứng minh.'), ('qmwgmy8q004w', 'b2ce278qf07k', 6, 'qcm', 'Quelle affirmation est présentée comme acceptée par tous ?', '{"options":["Le café est déconseillé à tous.","Le café protège efficacement tous les adultes contre les maladies du cœur.","Une consommation modérée n''est pas dangereuse."]}'::jsonb, '{"answer":2}'::jsonb, '« Une seule conclusion fait l''unanimité : … une consommation modérée n''est pas dangereuse ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce288qf07l', 'practice', 'Lecture B2 : quelle nuance ?', 'B2', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte. Faites attention aux mots qui indiquent le degré de certitude, la condition ou la concession, puis répondez aux questions.</p>', '<p><strong>La piscine Jean-Moulin restera-t-elle ouverte ?</strong></p><p>La piscine Jean-Moulin, construite en 1972, ferme ses portes pour l''été, comme chaque année. Cette fois pourtant, rien ne garantit qu''elle rouvrira en septembre. Le toit fuit, la chaudière date d''un autre siècle et, selon un rapport technique, la rénovation coûterait près de huit millions d''euros.</p><p>Le maire assure qu''aucune décision n''est prise. Il reconnaît néanmoins que la ville n''a pas les moyens de financer seule de tels travaux, à moins d''obtenir l''aide de la région. Celle-ci n''a, pour l''instant, rien promis.</p><p>Les clubs de natation, eux, ne cachent pas leur inquiétude. Si la piscine fermait, les deux cents enfants inscrits devraient se rendre à vingt kilomètres, dans une commune voisine dont le bassin est déjà saturé. Quant aux écoles, elles n''auraient tout simplement plus de lieu pour les cours de natation, pourtant obligatoires.</p><p>Certains élus de l''opposition proposent de construire un nouvel équipement plutôt que de rénover l''ancien. L''idée n''est pas absurde, même si elle suppose plusieurs années sans piscine. D''autres, plus pragmatiques, suggèrent une rénovation par étapes.</p><p>En attendant, une pétition a déjà recueilli trois mille signatures. Le maire a promis de les lire toutes. On ne doute pas qu''il trouvera le temps.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• fuir (verbe) : (mái) dột\n• une chaudière : nồi hơi\n• saturé (adjectif) : quá tải\n• pragmatique (adjectif) : thực tế\n• une pétition : bản kiến nghị","explications":"• Bài trộn: mỗi câu hỏi một sắc thái (chắc chắn, giả định, nhượng bộ, mỉa mai). Gạch chân từ khoá sắc thái trong câu trích trước khi chọn.\n• « pas absurde » (giảm nhẹ, litote) nghĩa là « khá hợp lý », không phải « tuyệt vời ».","isPremium":true,"price":19000,"kyNang":"B2-CE-4","vong":"chot","thuTu":5}'::jsonb, '2026-11-14T20:00:27.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8q004x', 'b2ce288qf07l', 1, 'qcm', 'La réouverture de la piscine en septembre est…', '{"options":["garantie.","incertaine.","impossible."]}'::jsonb, '{"answer":1}'::jsonb, '« rien ne garantit qu''elle rouvrira en septembre ».'), ('qmwgmy8q004y', 'b2ce288qf07l', 2, 'qcm', 'Le coût de la rénovation est présenté comme…', '{"options":["un montant voté par le conseil municipal.","une estimation tirée d''un rapport.","un chiffre avancé par l''opposition."]}'::jsonb, '{"answer":1}'::jsonb, '« selon un rapport technique, la rénovation coûterait »: thức điều kiện = ước tính.'), ('qmwgmy8q004z', 'b2ce288qf07l', 3, 'qcm', 'Que laisse entendre le maire ?', '{"options":["La piscine sera rénovée quoi qu''il arrive, même sans l''aide de personne.","La décision de fermer est déjà prise.","Sans aide extérieure, la rénovation paraît difficile."]}'::jsonb, '{"answer":2}'::jsonb, '« la ville n''a pas les moyens de financer seule de tels travaux, à moins d''obtenir l''aide de la région ».'), ('qmwgmy8q0050', 'b2ce288qf07l', 4, 'qcm', 'Quelle est la position de la région ?', '{"options":["Elle a promis de tout payer.","Elle ne s''est pas encore engagée.","Elle a refusé définitivement de participer aux travaux."]}'::jsonb, '{"answer":1}'::jsonb, '« n''a, pour l''instant, rien promis »: chưa hứa, nhưng cũng chưa từ chối.'), ('qmwgmy8q0051', 'b2ce288qf07l', 5, 'qcm', 'La phrase sur les deux cents enfants décrit…', '{"options":["une décision prise par les clubs.","une situation qui existe déjà dans la commune voisine.","une conséquence possible d''une fermeture."]}'::jsonb, '{"answer":2}'::jsonb, '« Si la piscine fermait, les deux cents enfants inscrits devraient »: giả định.'), ('qmwgmy8q0052', 'b2ce288qf07l', 6, 'qcm', 'Que dit l''article des cours de natation à l''école ?', '{"options":["Ils ne sont plus obligatoires depuis cette année.","Ils seront déplacés dans la commune voisine dès la rentrée de septembre.","Ils sont obligatoires mais pourraient ne plus avoir lieu."]}'::jsonb, '{"answer":2}'::jsonb, '« elles n''auraient tout simplement plus de lieu pour les cours de natation, pourtant obligatoires ».'), ('qmwgmy8q0053', 'b2ce288qf07l', 7, 'qcm', 'Comment l''auteur juge-t-il l''idée d''un nouvel équipement ?', '{"options":["Acceptable, malgré un inconvénient.","Ridicule et impossible à réaliser.","Parfaite et sans aucun défaut."]}'::jsonb, '{"answer":0}'::jsonb, '« L''idée n''est pas absurde, même si elle suppose plusieurs années sans piscine ».'), ('qmwgmy8q0054', 'b2ce288qf07l', 8, 'qcm', 'Quel est le ton de la dernière phrase ?', '{"options":["Neutre.","Admiratif.","Ironique."]}'::jsonb, '{"answer":2}'::jsonb, 'Ba nghìn chữ ký, ông hứa đọc hết: « On ne doute pas qu''il trouvera le temps » là mỉa mai.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce298qf07m', 'practice', 'Lecture B2 : soixante minutes, trois textes', 'B2', array['Lecture']::text[], 'practice', null, 40, '<p>Vous avez 40 minutes pour lire ces deux articles et répondre aux questions. Notez l''heure au début et à la fin de chaque texte : visez environ 20 minutes par texte. Le temps restant s''affiche en haut de l''écran ; à la fin du temps, vos réponses sont envoyées automatiquement.</p>', '<p><strong>Texte 1 : la sieste au bureau</strong></p><p>Dix-sept minutes. C''est la durée de la sieste que s''accordent chaque jour les salariés d''une entreprise de logiciels installée à Nantes. Depuis deux ans, une salle de repos équipée de fauteuils inclinables est ouverte de treize à quinze heures. Personne n''est obligé de l''utiliser, mais près d''un salarié sur trois y passe régulièrement.</p><p>Pour la directrice des ressources humaines, Laure Besson, il ne s''agit pas d''un gadget. « Après le déjeuner, la concentration chute. Plutôt que de lutter avec trois cafés, mieux vaut dormir un quart d''heure. Depuis l''ouverture de la salle, les erreurs dans le code ont diminué, et les arrêts maladie aussi. » Elle reconnaît toutefois qu''il est difficile de prouver que la sieste est la seule cause de ces progrès.</p><p>Les médecins du sommeil confirment l''intérêt d''une courte pause, à condition qu''elle ne dépasse pas vingt minutes : au-delà, on risque d''entrer dans un sommeil profond et de se réveiller encore plus fatigué. La sieste ne remplace pas non plus une bonne nuit, rappellent-ils.</p><p>Reste un obstacle culturel. En France, dormir au bureau passe encore souvent pour de la paresse. Plusieurs salariés avouent qu''ils ont mis des mois avant d''oser entrer dans la salle, de peur d''être mal vus par leur chef. Ce n''est que lorsque le directeur général lui-même a commencé à faire la sieste que les réticences ont disparu.</p><p><strong>Texte 2 : un potager au pied des immeubles</strong></p><p>Au pied des immeubles du quartier des Tilleuls, à Grenoble, une ancienne pelouse abandonnée est devenue un potager de huit cents mètres carrés. Une soixantaine de familles y cultivent tomates, courgettes et herbes aromatiques. Chacune dispose d''une petite parcelle, mais les outils, l''eau et le compost sont partagés.</p><p>L''initiative est venue de Fatou Diallo, une habitante arrivée il y a cinq ans. « Je ne connaissais personne. Je voyais des gens que je croisais tous les jours sans jamais leur parler. Le jardin, c''était un prétexte pour se rencontrer. » Aujourd''hui, des voisins qui s''ignoraient se donnent rendez-vous le samedi matin, échangent des recettes et surveillent les plantations des autres pendant les vacances.</p><p>Les légumes récoltés ne suffisent évidemment pas à nourrir une famille. Mais plusieurs jardiniers disent avoir changé leurs habitudes : ils achètent moins de plats préparés, cuisinent davantage et font découvrir aux enfants des légumes qu''ils refusaient de goûter.</p><p>Tout n''est pas simple pour autant. Il a fallu rédiger un règlement après des disputes sur l''arrosage, et quelques parcelles ont été abandonnées en cours de saison. La mairie, qui prête le terrain gratuitement, pourrait par ailleurs récupérer une partie de l''espace pour construire une école. Les jardiniers espèrent la convaincre de déplacer le projet de quelques mètres.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• s''accorder (verbe) : cho phép mình\n• une réticence : sự ngần ngại\n• un potager : vườn rau\n• une parcelle : mảnh đất nhỏ\n• un prétexte : cái cớ","explications":"• Đề B2 có 60 phút cho ba bài đọc. Bài này tập chia giờ: ghi giờ bắt đầu mỗi văn bản, quá 20 phút thì chọn đáp án hợp lý nhất rồi chuyển.\n• Đọc câu hỏi trước văn bản: câu hỏi đi theo thứ tự bài, bạn biết cần tìm gì ở mỗi đoạn.","kyNang":"B2-CE-5","vong":"hoc","thuTu":1}'::jsonb, '2026-11-14T20:00:28.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8q0055', 'b2ce298qf07m', 1, 'qcm', 'Texte 1. Que propose l''entreprise nantaise ?', '{"options":["Un lieu pour une courte sieste en début d''après-midi.","Des journées de travail plus courtes le vendredi pour tous les salariés.","Une cafétéria ouverte tard le soir pour l''équipe."]}'::jsonb, '{"answer":0}'::jsonb, '« une salle de repos équipée de fauteuils inclinables est ouverte de treize à quinze heures ».'), ('qmwgmy8q0056', 'b2ce298qf07m', 2, 'qcm', 'Texte 1. Combien de salariés utilisent la salle ?', '{"options":["Presque personne, par timidité.","Environ un tiers, régulièrement.","Tous, car elle est obligatoire."]}'::jsonb, '{"answer":1}'::jsonb, '« près d''un salarié sur trois y passe régulièrement ».'), ('qmwgmy8q0057', 'b2ce298qf07m', 3, 'qcm', 'Texte 1. Selon Laure Besson, la sieste est préférable…', '{"options":["à une séance de sport à l''heure du midi.","à une longue pause pour déjeuner dehors.","à plusieurs cafés pour rester concentré."]}'::jsonb, '{"answer":2}'::jsonb, '« Plutôt que de lutter avec trois cafés, mieux vaut dormir un quart d''heure ».'), ('qmwgmy8q0058', 'b2ce298qf07m', 4, 'qcm', 'Texte 1. Quelle réserve Laure Besson exprime-t-elle ?', '{"options":["Certains salariés dorment beaucoup trop longtemps.","Les progrès n''ont peut-être pas une seule cause.","La salle coûte trop cher à l''entreprise."]}'::jsonb, '{"answer":1}'::jsonb, '« difficile de prouver que la sieste est la seule cause de ces progrès ».'), ('qmwgmy8q0059', 'b2ce298qf07m', 5, 'qcm', 'Texte 1. Pourquoi la sieste ne doit-elle pas dépasser vingt minutes ?', '{"options":["Parce que la salle ferme à quinze heures précises.","Pour éviter de tomber dans un sommeil profond.","Parce que le chef contrôle le temps de chacun."]}'::jsonb, '{"answer":1}'::jsonb, '« au-delà, on risque d''entrer dans un sommeil profond ».'), ('qmwgmy8q005a', 'b2ce298qf07m', 6, 'qcm', 'Texte 1. Pourquoi certains salariés hésitaient-ils à utiliser la salle ?', '{"options":["Ils préféraient dormir chez eux à midi.","Ils trouvaient les fauteuils inconfortables.","Ils avaient peur d''être jugés paresseux."]}'::jsonb, '{"answer":2}'::jsonb, '« dormir au bureau passe encore souvent pour de la paresse… de peur d''être mal vus par leur chef ».'), ('qmwgmy8q005b', 'b2ce298qf07m', 7, 'qcm', 'Texte 1. Qu''est-ce qui a fait disparaître les réticences ?', '{"options":["Une étude des médecins du sommeil.","Une nouvelle règle de la direction.","L''exemple donné par le directeur."]}'::jsonb, '{"answer":2}'::jsonb, '« lorsque le directeur général lui-même a commencé à faire la sieste ».'), ('qmwgmy8q005c', 'b2ce298qf07m', 8, 'qcm', 'Texte 2. Comment le jardin est-il organisé ?', '{"options":["Chaque famille a sa parcelle, le matériel est commun.","Toutes les familles cultivent ensemble une seule parcelle.","La mairie choisit les légumes que chaque famille plante."]}'::jsonb, '{"answer":0}'::jsonb, '« Chacune dispose d''une petite parcelle, mais les outils, l''eau et le compost sont partagés ».'), ('qmwgmy8q005d', 'b2ce298qf07m', 9, 'qcm', 'Texte 2. Pourquoi Fatou Diallo a-t-elle lancé ce projet ?', '{"options":["Pour apprendre le jardinage aux enfants.","Pour vendre ses légumes au marché.","Pour créer des liens avec ses voisins."]}'::jsonb, '{"answer":2}'::jsonb, '« Le jardin, c''était un prétexte pour se rencontrer ».'), ('qmwgmy8q005e', 'b2ce298qf07m', 10, 'qcm', 'Texte 2. Qu''est-ce qui a changé entre les voisins ?', '{"options":["Ils se voient et s''entraident régulièrement.","Ils partent en vacances tous ensemble l''été.","Ils se disputent souvent au sujet des récoltes."]}'::jsonb, '{"answer":0}'::jsonb, 'Họ hẹn nhau sáng thứ Bảy và « surveillent les plantations des autres pendant les vacances ».'), ('qmwgmy8q005f', 'b2ce298qf07m', 11, 'qcm', 'Texte 2. Que dit l''article de la production de légumes ?', '{"options":["Elle permet de vendre des surplus chaque semaine.","Elle couvre tous les besoins des familles en été.","Elle ne suffit pas à nourrir une famille."]}'::jsonb, '{"answer":2}'::jsonb, '« ne suffisent évidemment pas à nourrir une famille ».'), ('qmwgmy8q005g', 'b2ce298qf07m', 12, 'qcm', 'Texte 2. Quel effet le jardin a-t-il eu sur l''alimentation ?', '{"options":["Les familles mangent plus souvent au restaurant.","Les enfants refusent encore plus les légumes.","Les familles cuisinent davantage elles-mêmes."]}'::jsonb, '{"answer":2}'::jsonb, '« ils achètent moins de plats préparés, cuisinent davantage ».'), ('qmwgmy8q005h', 'b2ce298qf07m', 13, 'qcm', 'Texte 2. Pourquoi un règlement a-t-il été rédigé ?', '{"options":["À la demande de la mairie de Grenoble.","À cause de disputes sur l''arrosage.","Pour fixer le prix de chaque parcelle."]}'::jsonb, '{"answer":1}'::jsonb, '« Il a fallu rédiger un règlement après des disputes sur l''arrosage ».'), ('qmwgmy8q005i', 'b2ce298qf07m', 14, 'qcm', 'Texte 2. Quelle menace pèse sur le jardin ?', '{"options":["La mairie pourrait reprendre une partie du terrain.","Les habitants veulent y construire un parking.","Le terrain va devenir payant dès l''an prochain."]}'::jsonb, '{"answer":0}'::jsonb, '« pourrait par ailleurs récupérer une partie de l''espace pour construire une école ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce308qf07n', 'practice', 'Lecture B2 : quand passer à la suite', 'B2', array['Lecture']::text[], 'practice', null, 20, '<p>Vous avez 20 minutes. Si une question vous bloque plus d''une minute, passez à la suivante et revenez-y à la fin. Le temps restant s''affiche en haut de l''écran ; à la fin du temps, vos réponses sont envoyées automatiquement.</p>', '<p><strong>Trottinettes en libre-service : la fin d''une époque ?</strong></p><p>Il y a quelques années, elles avaient envahi les trottoirs des grandes villes. Aujourd''hui, les trottinettes électriques en libre-service disparaissent de plusieurs capitales européennes. Après une consultation des habitants, Paris les a interdites en 2023 ; d''autres villes ont réduit le nombre d''appareils autorisés ou imposé des zones de stationnement.</p><p>Les opérateurs dénoncent une décision injuste. Selon eux, la trottinette remplace avant tout des trajets en voiture ou en taxi, et contribue donc à réduire la pollution. Les études disponibles nuancent fortement cet argument : la plupart des utilisateurs auraient sinon marché ou pris les transports en commun. Quant à la durée de vie des premiers modèles, elle ne dépassait parfois pas quelques mois, ce qui alourdissait leur bilan écologique.</p><p>Le principal reproche reste cependant la sécurité et l''occupation de l''espace public. Les piétons, en particulier les personnes âgées et malvoyantes, se plaignaient d''appareils abandonnés au milieu des trottoirs. Les accidents, souvent dus à une vitesse excessive ou à la présence de deux personnes sur la même trottinette, ont aussi pesé dans le débat.</p><p>Les utilisateurs, eux, regrettent un moyen de transport pratique, notamment pour les trajets de fin de soirée, quand les métros sont plus rares. Certains se sont tournés vers les vélos en libre-service, que la plupart des villes continuent d''encourager. Paradoxalement, les ventes de trottinettes personnelles ont augmenté depuis l''interdiction : ce n''est pas l''objet qui était rejeté, mais la manière dont il occupait la ville.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• en libre-service : cho thuê tự phục vụ\n• un opérateur : công ty khai thác\n• nuancer (verbe) : làm giảm bớt, điều chỉnh\n• alourdir (verbe) : làm nặng thêm\n• malvoyant (adjectif) : khiếm thị","explications":"• Câu 3, 4 và 7 khó hơn: chúng hỏi ý ngầm và từ « nuancent », « alourdissait ». Nếu kẹt quá một phút, đánh dấu, làm câu sau, rồi quay lại.\n• Không bỏ trống câu nào: đề B2 không trừ điểm câu sai, hết giờ thì chọn phương án hợp lý nhất.","isPremium":true,"price":19000,"kyNang":"B2-CE-5","vong":"hoc","thuTu":2}'::jsonb, '2026-11-14T20:00:29.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8q005j', 'b2ce308qf07n', 1, 'qcm', 'Que s''est-il passé à Paris ?', '{"options":["Le nombre de trottinettes a été multiplié par deux.","Les trottinettes personnelles ont été interdites.","Les trottinettes en libre-service ont été interdites."]}'::jsonb, '{"answer":2}'::jsonb, '« Paris les a interdites en 2023 » (xe cho thuê; xe riêng vẫn bán chạy hơn, xem đoạn cuối).'), ('qmwgmy8q005k', 'b2ce308qf07n', 2, 'qcm', 'Selon les opérateurs, les trottinettes…', '{"options":["coûtent moins cher que les transports publics.","sont plus sûres que les vélos de la ville.","remplacent surtout des trajets en voiture."]}'::jsonb, '{"answer":2}'::jsonb, '« la trottinette remplace avant tout des trajets en voiture ou en taxi ».'), ('qmwgmy8q005l', 'b2ce308qf07n', 3, 'qcm', 'Que montrent les études sur l''argument des opérateurs ?', '{"options":["Il est entièrement confirmé par les chercheurs.","Il n''a jamais été étudié.","Il est en grande partie contredit."]}'::jsonb, '{"answer":2}'::jsonb, 'Câu khó: « nuancent fortement » nghĩa là phần lớn không đúng, vì người dùng « auraient sinon marché ou pris les transports en commun ».'), ('qmwgmy8q005m', 'b2ce308qf07n', 4, 'qcm', 'Pourquoi le bilan écologique des premiers modèles était-il mauvais ?', '{"options":["Ils s''usaient très rapidement.","Ils étaient fabriqués très loin.","Ils roulaient à l''essence en ville."]}'::jsonb, '{"answer":0}'::jsonb, 'Câu khó: « la durée de vie… ne dépassait parfois pas quelques mois, ce qui alourdissait leur bilan écologique ».'), ('qmwgmy8q005n', 'b2ce308qf07n', 5, 'qcm', 'Qui se plaignait des trottinettes abandonnées ?', '{"options":["Les piétons fragiles, comme les malvoyants.","Les chauffeurs de taxi et de bus des grandes villes.","Les commerçants des grands boulevards."]}'::jsonb, '{"answer":0}'::jsonb, '« les personnes âgées et malvoyantes, se plaignaient d''appareils abandonnés ».'), ('qmwgmy8q005o', 'b2ce308qf07n', 6, 'qcm', 'Que regrettent les utilisateurs ?', '{"options":["Le prix très bas de la location à la minute.","Un moyen pratique, surtout tard le soir.","La possibilité de rouler à deux."]}'::jsonb, '{"answer":1}'::jsonb, '« notamment pour les trajets de fin de soirée, quand les métros sont plus rares ».'), ('qmwgmy8q005p', 'b2ce308qf07n', 7, 'qcm', 'Que montre la hausse des ventes de trottinettes personnelles ?', '{"options":["Les vélos en libre-service ont été supprimés.","Les habitants ont refusé la décision de la ville.","C''est l''usage en libre-service qui posait problème."]}'::jsonb, '{"answer":2}'::jsonb, 'Câu khó: « ce n''est pas l''objet qui était rejeté, mais la manière dont il occupait la ville ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce318qf07o', 'practice', 'Lecture B2 : lecture chronométrée', 'B2', array['Lecture']::text[], 'practice', null, 60, '<p>Comme à l''examen : trois textes en 60 minutes. Conseil : environ 20 minutes pour le texte 1, 20 minutes pour le texte 2, 15 minutes pour le forum, puis 5 minutes pour relire. Le temps restant s''affiche en haut de l''écran ; à la fin du temps, vos réponses sont envoyées automatiquement.</p>', '<p><strong>Texte 1 : le retour de la consigne</strong></p><p>Rapporter ses bouteilles vides au magasin et récupérer quelques centimes : nos grands-parents connaissaient bien ce geste, abandonné dans les années 1980 avec l''arrivée des emballages jetables. Aujourd''hui, la consigne revient. Dans plusieurs régions, des brasseries et des producteurs de jus de fruits proposent à nouveau des bouteilles en verre réutilisables.</p><p>Le principe est simple : le client paie quelques centimes de plus à l''achat, puis récupère cette somme en rapportant la bouteille. Celle-ci est lavée dans une usine spécialisée, puis remplie à nouveau, jusqu''à cinquante fois. Selon les professionnels du secteur, une bouteille réemployée consomme beaucoup moins d''énergie qu''une bouteille fabriquée ou même recyclée.</p><p>Encore faut-il que le système soit organisé à proximité. Transporter des bouteilles vides sur des centaines de kilomètres annule une grande partie du bénéfice. C''est pourquoi les réseaux qui fonctionnent le mieux sont régionaux, avec des laveries installées au plus près des producteurs.</p><p>Les grandes surfaces restent prudentes. Accepter les bouteilles vides demande de la place, du personnel et des machines. Certaines enseignes ont installé des automates de collecte ; d''autres attendent une loi qui imposerait la même règle à tous, pour ne pas supporter seules les coûts.</p><p>Du côté des consommateurs, l''accueil est plutôt favorable. Mais les habitudes sont tenaces : beaucoup oublient leurs bouteilles au fond d''un placard, et le taux de retour, essentiel à la rentabilité du système, reste encore insuffisant.</p><p><strong>Texte 2 : quand tout se passe en ligne</strong></p><p>Prendre rendez-vous chez le médecin, déclarer ses revenus, consulter ses remboursements : de plus en plus de démarches se font uniquement en ligne. Pour une partie de la population, cette évolution est un progrès. Pour d''autres, elle est devenue un véritable obstacle. On estime qu''environ une personne sur six en France rencontre des difficultés avec les outils numériques.</p><p>Contrairement à une idée reçue, toutes les personnes âgées ne sont pas concernées, et tous les jeunes ne sont pas à l''aise. Des étudiants très habiles sur les réseaux sociaux se retrouvent démunis face à un formulaire administratif. Inversement, de nombreux retraités échangent quotidiennement avec leurs petits-enfants par vidéo.</p><p>Pour aider ceux qui en ont besoin, des conseillers numériques ont été recrutés dans les mairies et les médiathèques. Ils accompagnent les usagers pas à pas, sans faire les démarches à leur place. L''objectif, explique l''un d''eux, est que la personne soit capable de recommencer seule la fois suivante.</p><p>Ces dispositifs ont toutefois leurs limites. Les rendez-vous sont parfois complets plusieurs semaines à l''avance, et les financements ne sont garantis que pour quelques années. Surtout, certaines associations rappellent qu''aucune formation ne remplacera la possibilité de parler à quelqu''un. Elles demandent que chaque service public conserve un accueil physique ou téléphonique.</p><p>Car le risque est clair : à force de tout dématérialiser, on pourrait exclure précisément ceux qui ont le plus besoin des services publics.</p><p><strong>Texte 3 : forum « Faut-il accepter les chiens au restaurant ? »</strong></p><p><strong>Valérie</strong></p><p>Je tiens un petit restaurant à Bordeaux et j''accepte les chiens depuis l''ouverture. Mes clients habitués viennent avec leur animal, et cela crée une ambiance familiale. Je pose simplement une règle : le chien reste sous la table et en laisse. En dix ans, je n''ai eu qu''un seul incident. Franchement, certains enfants font plus de bruit que les chiens !</p><p><strong>Julien</strong></p><p>J''ai une allergie sévère aux poils d''animaux. Quand un chien est assis à la table voisine, je dois quitter le restaurant au bout d''une demi-heure. Je ne demande pas d''interdire partout, mais qu''on indique clairement à l''entrée si les animaux sont acceptés. Comme ça, chacun peut choisir en connaissance de cause.</p><p><strong>Samia</strong></p><p>J''adore les chiens, j''en ai deux. Mais je ne les emmène jamais au restaurant : ils s''ennuient, ils ont chaud, ils sont stressés par le bruit. On croit leur faire plaisir, en réalité on se fait surtout plaisir à soi-même. Le restaurant, c''est un lieu pour les humains, pas pour les animaux.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la consigne : tiền cược vỏ chai\n• réemployer (verbe) : dùng lại\n• tenace (adjectif) : dai dẳng\n• démuni (adjectif) : lúng túng, không có phương tiện\n• dématérialiser (verbe) : số hoá, bỏ giấy tờ","explications":"• Ba văn bản liên tiếp: làm theo thứ tự đề, đừng quay lại văn bản trước khi chưa xong cả ba.\n• Diễn đàn làm nhanh nhất nếu đọc sáu nhận định trước. Giữ 5 phút cuối để kiểm tra không bỏ trống câu nào.","isPremium":true,"price":19000,"kyNang":"B2-CE-5","vong":"on","thuTu":3}'::jsonb, '2026-11-14T20:00:30.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8q005q', 'b2ce318qf07o', 1, 'qcm', 'Texte 1. Pourquoi la consigne avait-elle disparu ?', '{"options":["Parce que les clients refusaient de payer plus cher.","À cause de l''arrivée des emballages jetables.","Parce que les bouteilles en verre étaient interdites."]}'::jsonb, '{"answer":1}'::jsonb, '« abandonné dans les années 1980 avec l''arrivée des emballages jetables ».'), ('qmwgmy8q005r', 'b2ce318qf07o', 2, 'qcm', 'Texte 1. Comment fonctionne le système ?', '{"options":["On reçoit une bouteille gratuite pour dix rapportées.","On paie une taxe annuelle pour les bouteilles en verre.","On récupère une petite somme en rapportant la bouteille."]}'::jsonb, '{"answer":2}'::jsonb, '« récupère cette somme en rapportant la bouteille ».'), ('qmwgmy8q005s', 'b2ce318qf07o', 3, 'qcm', 'Texte 1. Combien de fois une bouteille peut-elle être remplie ?', '{"options":["Jusqu''à cinquante fois.","Une dizaine de fois au maximum.","Un nombre illimité de fois."]}'::jsonb, '{"answer":0}'::jsonb, '« remplie à nouveau, jusqu''à cinquante fois ».'), ('qmwgmy8q005t', 'b2ce318qf07o', 4, 'qcm', 'Texte 1. Selon les professionnels, quel est l''avantage du réemploi ?', '{"options":["Il crée beaucoup d''emplois dans les magasins.","Il rend les boissons moins chères pour tous.","Il consomme moins d''énergie que le recyclage."]}'::jsonb, '{"answer":2}'::jsonb, '« consomme beaucoup moins d''énergie qu''une bouteille fabriquée ou même recyclée ».'), ('qmwgmy8q005u', 'b2ce318qf07o', 5, 'qcm', 'Texte 1. Pourquoi les réseaux doivent-ils être régionaux ?', '{"options":["Le transport sur de longues distances réduit l''intérêt du système.","Les lois européennes interdisent de transporter le verre vide.","Les producteurs refusent de travailler avec d''autres régions."]}'::jsonb, '{"answer":0}'::jsonb, '« Transporter des bouteilles vides sur des centaines de kilomètres annule une grande partie du bénéfice ».'), ('qmwgmy8q005v', 'b2ce318qf07o', 6, 'qcm', 'Texte 1. Que souhaitent certaines grandes surfaces ?', '{"options":["La fin définitive de la consigne en magasin.","Une règle commune pour partager les coûts.","Des aides publiques pour vendre plus de verre."]}'::jsonb, '{"answer":1}'::jsonb, '« attendent une loi qui imposerait la même règle à tous, pour ne pas supporter seules les coûts ».'), ('qmwgmy8q005w', 'b2ce318qf07o', 7, 'qcm', 'Texte 1. Quel problème vient des consommateurs ?', '{"options":["Ils refusent de payer quelques centimes de plus.","Ils trouvent les bouteilles en verre trop lourdes.","Ils oublient souvent de rapporter les bouteilles."]}'::jsonb, '{"answer":2}'::jsonb, '« beaucoup oublient leurs bouteilles au fond d''un placard ».'), ('qmwgmy8q005x', 'b2ce318qf07o', 8, 'qcm', 'Texte 2. Quel constat l''article fait-il au début ?', '{"options":["La plupart des Français refusent encore d''utiliser internet chez eux.","Les services publics ferment le week-end.","Beaucoup de démarches ne se font plus qu''en ligne."]}'::jsonb, '{"answer":2}'::jsonb, '« de plus en plus de démarches se font uniquement en ligne ».'), ('qmwgmy8q005y', 'b2ce318qf07o', 9, 'qcm', 'Texte 2. Quelle idée reçue l''auteur conteste-t-il ?', '{"options":["Que les formulaires en ligne sont plus rapides.","Que les jeunes passent trop de temps sur les réseaux.","Que seules les personnes âgées ont des difficultés."]}'::jsonb, '{"answer":2}'::jsonb, '« toutes les personnes âgées ne sont pas concernées, et tous les jeunes ne sont pas à l''aise ».'), ('qmwgmy8q005z', 'b2ce318qf07o', 10, 'qcm', 'Texte 2. Que dit l''article de certains étudiants ?', '{"options":["Ils sont à l''aise en ligne, mais pas avec l''administration.","Ils travaillent comme conseillers numériques dans les mairies.","Ils aident souvent leurs grands-parents à faire leurs démarches."]}'::jsonb, '{"answer":0}'::jsonb, '« très habiles sur les réseaux sociaux se retrouvent démunis face à un formulaire administratif ».'), ('qmwgmy8q0060', 'b2ce318qf07o', 11, 'qcm', 'Texte 2. Quel est l''objectif des conseillers numériques ?', '{"options":["Vendre du matériel informatique.","Rendre les usagers autonomes.","Faire les démarches à leur place."]}'::jsonb, '{"answer":1}'::jsonb, '« sans faire les démarches à leur place… capable de recommencer seule la fois suivante ».'), ('qmwgmy8q0061', 'b2ce318qf07o', 12, 'qcm', 'Texte 2. Quelle limite de ces dispositifs est mentionnée ?', '{"options":["Leur financement n''est pas assuré à long terme.","Les conseillers manquent de formation technique.","Les usagers ne viennent jamais aux rendez-vous."]}'::jsonb, '{"answer":0}'::jsonb, '« les financements ne sont garantis que pour quelques années ».'), ('qmwgmy8q0062', 'b2ce318qf07o', 13, 'qcm', 'Texte 2. Que demandent certaines associations ?', '{"options":["Supprimer les démarches en ligne pour les retraités.","Garder un accueil humain dans les services publics.","Former tous les enfants à l''informatique dès l''école."]}'::jsonb, '{"answer":1}'::jsonb, '« conserve un accueil physique ou téléphonique ».'), ('qmwgmy8q0063', 'b2ce318qf07o', 14, 'qcm', 'Texte 2. Quel risque l''auteur souligne-t-il en conclusion ?', '{"options":["Rendre les services publics beaucoup trop chers pour l''État et les communes.","Exclure ceux qui ont le plus besoin des services publics.","Augmenter le nombre de fraudes sur internet."]}'::jsonb, '{"answer":1}'::jsonb, '« on pourrait exclure précisément ceux qui ont le plus besoin des services publics ».'), ('qmwgmy8q0064', 'b2ce318qf07o', 15, 'qcm', 'Texte 3. Elle pense que les propriétaires de chiens pensent surtout à eux-mêmes.', '{"options":["Valérie","Julien","Samia"]}'::jsonb, '{"answer":2}'::jsonb, 'Samia : « en réalité on se fait surtout plaisir à soi-même ».'), ('qmwgmy8q0065', 'b2ce318qf07o', 16, 'qcm', 'Texte 3. Une information claire permettrait à chacun de choisir.', '{"options":["Valérie","Julien","Samia"]}'::jsonb, '{"answer":1}'::jsonb, 'Julien : « chacun peut choisir en connaissance de cause ».'), ('qmwgmy8q0066', 'b2ce318qf07o', 17, 'qcm', 'Texte 3. Accueillir les chiens n''a presque jamais posé de problème.', '{"options":["Valérie","Julien","Samia"]}'::jsonb, '{"answer":0}'::jsonb, 'Valérie : « En dix ans, je n''ai eu qu''un seul incident ».'), ('qmwgmy8q0067', 'b2ce318qf07o', 18, 'qcm', 'Texte 3. Il évoque une raison de santé.', '{"options":["Valérie","Julien","Samia"]}'::jsonb, '{"answer":1}'::jsonb, 'Julien : « J''ai une allergie sévère aux poils d''animaux ».'), ('qmwgmy8q0068', 'b2ce318qf07o', 19, 'qcm', 'Texte 3. Le restaurant n''est pas adapté au bien-être des animaux.', '{"options":["Valérie","Julien","Samia"]}'::jsonb, '{"answer":2}'::jsonb, 'Samia : « ils s''ennuient, ils ont chaud, ils sont stressés par le bruit ».'), ('qmwgmy8q0069', 'b2ce318qf07o', 20, 'qcm', 'Texte 3. Elle impose des conditions aux clients accompagnés d''un chien.', '{"options":["Valérie","Julien","Samia"]}'::jsonb, '{"answer":0}'::jsonb, 'Valérie : « le chien reste sous la table et en laisse ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b2ce328qf07p', 'practice', 'Lecture B2 : une heure, vingt questions', 'B2', array['Lecture']::text[], 'practice', null, 60, '<p>Comme à l''examen : trois textes en 60 minutes. Conseil : environ 20 minutes pour le texte 1, 20 minutes pour le texte 2, 15 minutes pour le forum, puis 5 minutes pour relire. Le temps restant s''affiche en haut de l''écran ; à la fin du temps, vos réponses sont envoyées automatiquement.</p>', '<p><strong>Texte 1 : la semaine de quatre jours</strong></p><p>Travailler quatre jours au lieu de cinq, sans baisse de salaire : l''idée séduit de plus en plus d''entreprises. Au Royaume-Uni, une expérience menée pendant six mois dans une soixantaine de sociétés a donné des résultats encourageants. La plupart d''entre elles ont choisi de prolonger l''essai, et une grande majorité de salariés ont déclaré se sentir moins épuisés.</p><p>En France, le modèle prend des formes variées. Certaines entreprises réduisent réellement le temps de travail, à trente-deux heures par semaine. D''autres se contentent de répartir les trente-cinq heures habituelles sur quatre journées plus longues. Pour les syndicats, la différence est essentielle : dans le second cas, la fatigue quotidienne augmente, et le bénéfice pour la santé n''est pas garanti.</p><p>Pour les dirigeants convaincus, la semaine de quatre jours est aussi un argument pour recruter. Dans les secteurs où les candidats sont rares, comme l''informatique ou la restauration, offrir un jour libre supplémentaire permet de se démarquer des concurrents. Certains constatent également une baisse de l''absentéisme.</p><p>Le modèle ne convient pas à tous les métiers. Dans un hôpital, une école ou un commerce ouvert six jours sur sept, il faut embaucher davantage pour assurer la continuité du service, ce qui augmente les coûts. Les petites entreprises, qui comptent parfois trois ou quatre salariés, ont plus de mal à s''organiser.</p><p>Les chercheurs qui ont suivi ces expériences restent prudents. Les entreprises volontaires étaient sans doute déjà les mieux préparées au changement. Rien ne dit que les résultats seraient identiques si la mesure était imposée à tous.</p><p><strong>Texte 2 : rendre la nuit à la nuit</strong></p><p>Vue de l''espace, l''Europe la nuit ressemble à une toile d''araignée lumineuse. Sur terre, la conséquence est simple : dans les grandes villes, il est devenu presque impossible de voir la Voie lactée. Selon les astronomes, plus d''un tiers de l''humanité ne peut plus l''observer depuis chez soi.</p><p>Longtemps considérée comme une gêne pour les seuls astronomes, la pollution lumineuse inquiète désormais les biologistes. De nombreux insectes, attirés par les lampadaires, tournent autour jusqu''à l''épuisement. Les oiseaux migrateurs, qui s''orientent la nuit, sont désorientés par les villes éclairées. Chez l''être humain, l''exposition à la lumière la nuit perturberait la production de mélatonine, l''hormone du sommeil.</p><p>Face à ces constats, de plus en plus de communes éteignent l''éclairage public au milieu de la nuit, souvent entre une heure et cinq heures du matin. La mesure permet aussi de réaliser des économies importantes sur la facture d''électricité, argument qui a convaincu bien des maires.</p><p>Certains habitants s''inquiètent pourtant pour leur sécurité. Les études menées dans les villes concernées ne montrent pas d''augmentation des cambriolages ou des agressions, la plupart ayant lieu en soirée, quand les lampadaires sont encore allumés. Mais le sentiment d''insécurité, lui, ne se mesure pas toujours avec des chiffres.</p><p>Entre l''obscurité totale et l''éclairage permanent, des solutions existent : des lampes orientées vers le sol, une lumière moins blanche, des détecteurs qui allument les rues seulement au passage des piétons. Retrouver la nuit ne signifie pas renoncer à la lumière, mais apprendre à l''utiliser là où elle est utile.</p><p><strong>Texte 3 : forum « Faut-il un service civique obligatoire pour les jeunes ? »</strong></p><p><strong>Bruno</strong></p><p>J''ai fait mon service militaire il y a quarante ans, et j''y ai rencontré des jeunes que je n''aurais jamais croisés autrement : des paysans, des étudiants, des ouvriers. Aujourd''hui, chacun vit dans sa bulle. Six mois au service des autres, dans un hôpital ou une association, permettraient de recréer ce mélange. Et il faudrait que ce soit obligatoire, sinon seuls les plus motivés le feraient.</p><p><strong>Clara</strong></p><p>J''ai vingt ans et j''ai choisi de faire un service civique dans une épicerie solidaire. C''était une expérience formidable, justement parce que je l''avais choisie. Si on m''avait forcée, je l''aurais vécue comme une punition. L''engagement ne se décrète pas : il faut plutôt mieux faire connaître les missions et mieux les rémunérer.</p><p><strong>Malik</strong></p><p>Qui va encadrer des centaines de milliers de jeunes chaque année ? Les associations manquent déjà de bénévoles et de moyens. Avant de parler d''obligation, il faudrait savoir combien cela coûte et qui paiera. Sur le principe, je ne suis pas contre, mais je crains qu''on lance une belle idée sans se donner les moyens de la réaliser.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• se démarquer (verbe) : nổi bật, khác biệt\n• l''absentéisme (nom masculin) : tình trạng nghỉ làm\n• la Voie lactée : dải Ngân Hà\n• un cambriolage : vụ trộm đột nhập\n• ne pas se décréter : không thể ra lệnh mà có","explications":"• Đúng điều kiện thi: 60 phút, tự nộp khi hết giờ. Làm xong thì so thời gian thực tế với kế hoạch 20 + 20 + 15 + 5.\n• Câu trong bài 2 có bẫy lẫn chủ thể (côn trùng / chim): khi hai đối tượng đứng gần nhau, đọc lại câu trích.","isPremium":true,"price":19000,"kyNang":"B2-CE-5","vong":"chot","thuTu":4}'::jsonb, '2026-11-14T20:00:31.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmwgmy8q006a', 'b2ce328qf07p', 1, 'qcm', 'Texte 1. Qu''a montré l''expérience menée au Royaume-Uni ?', '{"options":["Des résultats plutôt positifs.","Un échec dans la plupart des sociétés.","Aucun effet mesurable sur les salariés."]}'::jsonb, '{"answer":0}'::jsonb, '« a donné des résultats encourageants ».'), ('qmwgmy8q006b', 'b2ce328qf07p', 2, 'qcm', 'Texte 1. Comment les salariés britanniques ont-ils réagi ?', '{"options":["Ils ont préféré revenir à cinq jours.","Ils ont demandé une hausse de salaire.","Ils se sentaient moins fatigués."]}'::jsonb, '{"answer":2}'::jsonb, '« une grande majorité de salariés ont déclaré se sentir moins épuisés ».'), ('qmwgmy8q006c', 'b2ce328qf07p', 3, 'qcm', 'Texte 1. Quelle différence existe entre les entreprises françaises ?', '{"options":["Certaines réduisent les heures, d''autres les concentrent.","Certaines ferment le lundi, d''autres le samedi.","Certaines paient plus, d''autres réduisent les salaires."]}'::jsonb, '{"answer":0}'::jsonb, 'Có nơi giảm thật xuống 32 giờ, có nơi chỉ « répartir les trente-cinq heures habituelles sur quatre journées plus longues ».'), ('qmwgmy8q006d', 'b2ce328qf07p', 4, 'qcm', 'Texte 1. Que craignent les syndicats ?', '{"options":["Que les salariés perdent une partie de leur salaire.","Que des journées plus longues fatiguent davantage.","Que les entreprises recrutent moins de jeunes."]}'::jsonb, '{"answer":1}'::jsonb, '« dans le second cas, la fatigue quotidienne augmente ».'), ('qmwgmy8q006e', 'b2ce328qf07p', 5, 'qcm', 'Texte 1. Pourquoi certains dirigeants adoptent-ils ce modèle ?', '{"options":["Pour attirer des candidats rares.","Pour fermer certains de leurs bureaux.","Pour réduire le prix de leurs produits."]}'::jsonb, '{"answer":0}'::jsonb, '« offrir un jour libre supplémentaire permet de se démarquer des concurrents ».'), ('qmwgmy8q006f', 'b2ce328qf07p', 6, 'qcm', 'Texte 1. Pourquoi le modèle est-il difficile dans un hôpital ?', '{"options":["Les soignants refusent de travailler plus longtemps.","La loi interdit d''y modifier les horaires.","Il faudrait recruter plus pour assurer le service."]}'::jsonb, '{"answer":2}'::jsonb, '« il faut embaucher davantage pour assurer la continuité du service ».'), ('qmwgmy8q006g', 'b2ce328qf07p', 7, 'qcm', 'Texte 1. Pourquoi les chercheurs restent-ils prudents ?', '{"options":["L''expérience a duré beaucoup trop peu de temps.","Les résultats britanniques ont été mal calculés par les entreprises elles-mêmes.","Les entreprises testées étaient peut-être mieux préparées."]}'::jsonb, '{"answer":2}'::jsonb, '« Les entreprises volontaires étaient sans doute déjà les mieux préparées au changement ».'), ('qmwgmy8q006h', 'b2ce328qf07p', 8, 'qcm', 'Texte 2. Quelle conséquence de l''éclairage est citée en premier ?', '{"options":["Les insectes disparaissent des jardins.","On ne voit plus la Voie lactée en ville.","Les factures d''électricité augmentent."]}'::jsonb, '{"answer":1}'::jsonb, '« il est devenu presque impossible de voir la Voie lactée ».'), ('qmwgmy8q006i', 'b2ce328qf07p', 9, 'qcm', 'Texte 2. Qui s''inquiète désormais de la pollution lumineuse ?', '{"options":["Les biologistes, pas seulement les astronomes.","Les maires des grandes villes, avant tous les autres.","Les médecins, plus que les astronomes."]}'::jsonb, '{"answer":0}'::jsonb, '« Longtemps considérée comme une gêne pour les seuls astronomes… inquiète désormais les biologistes ».'), ('qmwgmy8q006j', 'b2ce328qf07p', 10, 'qcm', 'Texte 2. Quel effet la lumière a-t-elle sur les oiseaux migrateurs ?', '{"options":["Elle les empêche de bien s''orienter.","Elle les attire jusqu''à l''épuisement.","Elle les pousse à migrer plus tôt."]}'::jsonb, '{"answer":0}'::jsonb, '« sont désorientés par les villes éclairées ». Bị hút tới kiệt sức là côn trùng, không phải chim.'), ('qmwgmy8q006k', 'b2ce328qf07p', 11, 'qcm', 'Texte 2. L''effet de la lumière sur le sommeil humain est présenté comme…', '{"options":["inexistant selon les biologistes.","probable, mais pas certain.","démontré par tous les chercheurs."]}'::jsonb, '{"answer":1}'::jsonb, 'Thức điều kiện: « perturberait la production de mélatonine ».'), ('qmwgmy8q006l', 'b2ce328qf07p', 12, 'qcm', 'Texte 2. Qu''est-ce qui a convaincu de nombreux maires ?', '{"options":["La demande des habitants inquiets.","Les plaintes des astronomes amateurs.","Les économies sur l''électricité."]}'::jsonb, '{"answer":2}'::jsonb, '« des économies importantes sur la facture d''électricité, argument qui a convaincu bien des maires ».'), ('qmwgmy8q006m', 'b2ce328qf07p', 13, 'qcm', 'Texte 2. Que montrent les études sur la sécurité ?', '{"options":["Les habitants se sentent tous plus en sécurité.","Les cambriolages ont doublé après une heure du matin.","Les délits n''ont pas augmenté avec l''extinction."]}'::jsonb, '{"answer":2}'::jsonb, '« ne montrent pas d''augmentation des cambriolages ou des agressions ».'), ('qmwgmy8q106n', 'b2ce328qf07p', 14, 'qcm', 'Texte 2. Quelle idée l''article défend-il en conclusion ?', '{"options":["Éteindre toutes les lumières la nuit.","Garder l''éclairage public permanent.","Éclairer seulement là où c''est utile."]}'::jsonb, '{"answer":2}'::jsonb, '« apprendre à l''utiliser là où elle est utile ».'), ('qmwgmy8q106o', 'b2ce328qf07p', 15, 'qcm', 'Texte 3. Il craint un projet mal financé.', '{"options":["Bruno","Clara","Malik"]}'::jsonb, '{"answer":2}'::jsonb, 'Malik : « je crains qu''on lance une belle idée sans se donner les moyens de la réaliser ».'), ('qmwgmy8q106p', 'b2ce328qf07p', 16, 'qcm', 'Texte 3. Un engagement imposé perdrait son sens.', '{"options":["Bruno","Clara","Malik"]}'::jsonb, '{"answer":1}'::jsonb, 'Clara : « L''engagement ne se décrète pas ».'), ('qmwgmy8q106q', 'b2ce328qf07p', 17, 'qcm', 'Texte 3. Ce service permettrait de mélanger les milieux sociaux.', '{"options":["Bruno","Clara","Malik"]}'::jsonb, '{"answer":0}'::jsonb, 'Bruno : « permettraient de recréer ce mélange ».'), ('qmwgmy8q106r', 'b2ce328qf07p', 18, 'qcm', 'Texte 3. Elle souhaite que les volontaires soient mieux payés.', '{"options":["Bruno","Clara","Malik"]}'::jsonb, '{"answer":1}'::jsonb, 'Clara : « mieux les rémunérer ».'), ('qmwgmy8q106s', 'b2ce328qf07p', 19, 'qcm', 'Texte 3. Sans obligation, seuls certains jeunes participeraient.', '{"options":["Bruno","Clara","Malik"]}'::jsonb, '{"answer":0}'::jsonb, 'Bruno : « sinon seuls les plus motivés le feraient ».'), ('qmwgmy8q106t', 'b2ce328qf07p', 20, 'qcm', 'Texte 3. Il doute que les structures d''accueil soient prêtes.', '{"options":["Bruno","Clara","Malik"]}'::jsonb, '{"answer":2}'::jsonb, 'Malik : « Les associations manquent déjà de bénévoles et de moyens ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
